window.QB_TKP_B24 = [
{"id":"TKP-4551","q":"Seorang rekan satu tim selalu menunda pekerjaannya hingga mendekati tenggat sehingga seluruh tim ikut terburu-buru. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajaknya berdiskusi empat mata untuk memahami kendalanya lalu menyepakati pembagian jadwal kerja yang realistis","s":5},{"t":"Menawarkan bantuan mengerjakan sebagian tugasnya agar tenggat tim tetap terpenuhi","s":4},{"t":"Melaporkan kebiasaannya kepada koordinator tim agar diberi teguran","s":3},{"t":"Membiarkannya karena itu tanggung jawab pribadinya, bukan urusan saya","s":2},{"t":"Mengerjakan seluruh tugasnya diam-diam agar tim tidak dinilai buruk","s":1}],"ex":"Diskusi empat mata menjaga hubungan baik sekaligus menyelesaikan akar masalah tanpa mengorbankan tenggat tim."},
{"id":"TKP-4552","q":"Rekan kerja Anda jarang berkomunikasi dan sering melewatkan informasi penting dalam grup kerja tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengajaknya berbicara langsung dan menyepakati cara komunikasi yang disepakati seluruh tim","s":5},{"t":"Selalu mengingatkannya secara pribadi setiap ada informasi penting","s":4},{"t":"Meminta koordinator tim mewajibkan semua anggota aktif berkomunikasi","s":3},{"t":"Mengabaikannya karena berkomunikasi adalah kewajiban masing-masing","s":2},{"t":"Menyindirnya di depan anggota tim lain agar ia malu dan berubah","s":1}],"ex":"Kesepakatan komunikasi yang dibangun bersama lebih efektif dan tidak merusak hubungan kerja."},
{"id":"TKP-4553","q":"Dalam sebuah tim proyek, seorang rekan bersikap pasif dan tidak pernah menyampaikan pendapat saat diskusi. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Memberinya ruang dan kesempatan khusus untuk menyampaikan pandangannya dalam diskusi tim","s":5},{"t":"Menanyakan pendapatnya secara pribadi setelah diskusi selesai","s":4},{"t":"Membiarkannya pasif karena setiap orang punya gaya kerja sendiri","s":3},{"t":"Memintanya keluar dari tim karena tidak berkontribusi","s":2},{"t":"Mengambil alih seluruh pekerjaannya agar proyek tetap berjalan","s":1}],"ex":"Memberi ruang aman untuk berpendapat mengaktifkan anggota pasif tanpa tekanan."},
{"id":"TKP-4554","q":"Rekan satu tim Anda mudah tersinggung setiap kali menerima kritik atas hasil kerjanya. Tindakan paling tepat adalah ....","opts":[{"t":"Menyampaikan masukan dengan bahasa yang membangun dan fokus pada hasil kerja, bukan pribadinya","s":5},{"t":"Meminta anggota tim lain yang lebih dekat dengannya untuk menyampaikan masukan","s":4},{"t":"Berhenti memberi masukan kepadanya agar tidak terjadi konflik","s":3},{"t":"Mengkritiknya lebih keras agar ia terbiasa menerima kritik","s":2},{"t":"Melaporkan sikapnya sebagai penghambat kerja tim","s":1}],"ex":"Kritik yang membangun dan berfokus pada pekerjaan menjaga kualitas tanpa melukai hubungan."},
{"id":"TKP-4555","q":"Seorang rekan selalu mengklaim keberhasilan tim sebagai hasil kerja pribadinya. Sikap terbaik Anda adalah ....","opts":[{"t":"Tetap profesional dan memastikan kontribusi tiap anggota tercatat dalam laporan tim","s":5},{"t":"Mengingatkannya secara pribadi bahwa keberhasilan adalah hasil kerja bersama","s":4},{"t":"Membiarkannya karena yang penting pekerjaan selesai dengan baik","s":3},{"t":"Melakukan hal yang sama agar tidak kalah pengakuan","s":2},{"t":"Menyebarkan cerita tentang perilakunya ke unit lain","s":1}],"ex":"Dokumentasi kontribusi yang objektif melindungi seluruh tim tanpa perlu konfrontasi personal."},
{"id":"TKP-4556","q":"Rekan kerja Anda sering memotong pembicaraan anggota tim lain saat diskusi. Cara terbaik mengatasinya adalah ....","opts":[{"t":"Menyepakati aturan diskusi tim, misalnya setiap orang bicara bergiliran","s":5},{"t":"Menegurnya secara halus saat ia memotong pembicaraan","s":4},{"t":"Membiarkannya karena ia mungkin tidak sadar","s":3},{"t":"Berhenti ikut diskusi ketika ia mulai banyak bicara","s":2},{"t":"Memotong balik pembicaraannya agar ia merasakan hal yang sama","s":1}],"ex":"Aturan diskusi yang disepakati bersama menyelesaikan masalah secara sistemik, bukan personal."},
{"id":"TKP-4557","q":"Seorang rekan satu tim menolak mengerjakan tugas yang menurutnya bukan bagiannya, padahal tim sedang kekurangan orang. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajaknya berdiskusi untuk menata ulang pembagian tugas sesuai kondisi darurat tim","s":5},{"t":"Menawarkan bertukar tugas dengannya agar ia mau membantu","s":4},{"t":"Memaksa dan mengancam akan melaporkannya","s":3},{"t":"Membiarkan tugasnya terbengkalai sebagai konsekuensi pilihannya","s":2},{"t":"Mengerjakan tugasnya sendiri tanpa memberitahunya","s":1}],"ex":"Penataan ulang tugas yang disepakati bersama adalah solusi darurat yang adil bagi tim."},
{"id":"TKP-4558","q":"Rekan kerja Anda menyebarkan gosip tentang anggota tim lain di lingkungan kerja. Sikap terbaik Anda adalah ....","opts":[{"t":"Tidak ikut menyebarkan dan mengajaknya fokus pada pekerjaan tim","s":5},{"t":"Menasihatinya secara pribadi agar menghentikan kebiasaannya","s":4},{"t":"Mendengarkan saja tanpa ikut menanggapi","s":3},{"t":"Ikut bergosip agar tidak dikucilkan dari pergaulan","s":2},{"t":"Menyebarkan gosip balasan tentang dirinya","s":1}],"ex":"Menolak ikut bergosip dan mengarahkan kembali ke pekerjaan menjaga kekompakan tim."},
{"id":"TKP-4559","q":"Seorang rekan dalam tim Anda bekerja sangat lambat sehingga menghambat penyelesaian tugas bersama. Cara terbaik adalah ....","opts":[{"t":"Menawarkan bantuan dan mencari tahu apakah ia mengalami kesulitan teknis","s":5},{"t":"Mengusulkan pembagian ulang tugas sesuai kecepatan masing-masing anggota","s":4},{"t":"Memintanya mempercepat kerjanya dengan nada tegas","s":3},{"t":"Mengeluhkannya kepada anggota tim lain","s":2},{"t":"Mengambil alih pekerjaannya tanpa sepengetahuannya","s":1}],"ex":"Memahami kesulitan rekan dan menyesuaikan pembagian tugas menyelesaikan hambatan tanpa konflik."},
{"id":"TKP-4560","q":"Rekan satu tim Anda sering menyalahkan orang lain setiap ada kesalahan dalam pekerjaan tim. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak tim melakukan evaluasi objektif dengan fokus pada perbaikan sistem kerja","s":5},{"t":"Mengingatkannya secara pribadi bahwa kesalahan tim adalah tanggung jawab bersama","s":4},{"t":"Membiarkannya karena setiap orang punya cara membela diri","s":3},{"t":"Membalas menyalahkannya di depan tim","s":2},{"t":"Menghindari bekerja satu tim dengannya di masa depan","s":1}],"ex":"Evaluasi yang fokus pada sistem, bukan menyalahkan orang, membangun budaya tim yang sehat."},
{"id":"TKP-4561","q":"Seorang rekan kerja baru terlihat canggung dan sulit berbaur dengan tim Anda. Sikap terbaik Anda adalah ....","opts":[{"t":"Aktif mengajaknya berinteraksi dan melibatkannya dalam kegiatan tim","s":5},{"t":"Menawarkan diri menjadi tempat bertanya selama masa adaptasinya","s":4},{"t":"Membiarkannya beradaptasi sendiri sesuai waktunya","s":3},{"t":"Menjauhinya karena ia belum terbukti kemampuannya","s":2},{"t":"Mengujinya dengan tugas berat agar cepat terbiasa","s":1}],"ex":"Keterlibatan aktif mempercepat adaptasi anggota baru dan memperkuat kekompakan tim."},
{"id":"TKP-4562","q":"Rekan satu tim Anda memiliki gaya kerja yang sangat berbeda dan sering menimbulkan gesekan. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mendiskusikan perbedaan tersebut dan mencari titik temu dalam cara kerja tim","s":5},{"t":"Menyesuaikan diri dengan gayanya selama tidak merugikan hasil tim","s":4},{"t":"Memintanya mengubah gaya kerjanya mengikuti mayoritas","s":3},{"t":"Menghindari kolaborasi dengannya sebisa mungkin","s":2},{"t":"Mengeluhkan gaya kerjanya kepada tim lain","s":1}],"ex":"Dialog terbuka tentang perbedaan gaya kerja menghasilkan kesepakatan yang diterima semua pihak."},
{"id":"TKP-4563","q":"Seorang rekan selalu datang terlambat ke pertemuan tim sehingga agenda molor. Tindakan paling tepat adalah ....","opts":[{"t":"Menyepakati bersama aturan ketepatan waktu yang berlaku untuk seluruh anggota tim","s":5},{"t":"Mengingatkannya secara pribadi tentang dampak keterlambatannya","s":4},{"t":"Memulai pertemuan tepat waktu tanpa menunggunya","s":3},{"t":"Membiarkannya karena menegur bisa menyinggung perasaan","s":2},{"t":"Sengaja datang terlambat juga sebagai protes","s":1}],"ex":"Aturan ketepatan waktu yang disepakati bersama berlaku adil untuk semua anggota tim."},
{"id":"TKP-4564","q":"Rekan kerja Anda menolak menggunakan cara kerja baru yang disepakati tim dan tetap memakai cara lama. Sikap terbaik adalah ....","opts":[{"t":"Menjelaskan manfaat cara baru dan mendampinginya selama masa penyesuaian","s":5},{"t":"Memberinya waktu sambil menunjukkan contoh keberhasilan cara baru","s":4},{"t":"Memaksanya mengikuti kesepakatan tim tanpa kecuali","s":3},{"t":"Membiarkannya memakai cara lama asal hasilnya sama","s":2},{"t":"Melaporkannya sebagai pembangkang kesepakatan tim","s":1}],"ex":"Pendampingan dan penjelasan manfaat membantu transisi tanpa paksaan."},
{"id":"TKP-4565","q":"Dalam tim Anda ada rekan yang sangat dominan dan selalu ingin keputusannya yang dipakai. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan mekanisme pengambilan keputusan tim yang demokratis dan disepakati bersama","s":5},{"t":"Menyampaikan keberatan secara terbuka namun sopan dalam forum tim","s":4},{"t":"Mengikuti saja keputusannya demi menghindari perdebatan","s":3},{"t":"Membentuk kubu tandingan untuk melawannya","s":2},{"t":"Menarik diri dari tim tersebut","s":1}],"ex":"Mekanisme keputusan yang demokratis menyeimbangkan dominasi satu anggota secara struktural."},
{"id":"TKP-4566","q":"Seorang rekan satu tim meminta Anda mengerjakan tugasnya dengan alasan sibuk, padahal ia terlihat santai. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak dengan sopan sambil menawarkan membantu memprioritaskan pekerjaannya","s":5},{"t":"Membantunya sekali ini sambil mengingatkannya agar tidak terulang","s":4},{"t":"Langsung menolak tanpa penjelasan","s":3},{"t":"Mengerjakannya dengan terpaksa agar tidak ribut","s":2},{"t":"Mengerjakannya lalu menuntut imbalan darinya","s":1}],"ex":"Penolakan sopan disertai tawaran solusi menjaga batasan sehat tanpa merusak hubungan."},
{"id":"TKP-4567","q":"Rekan kerja Anda terlihat murung dan hasil kerjanya menurun dalam tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Menanyakan keadaannya dengan empati dan menawarkan dukungan yang ia butuhkan","s":5},{"t":"Memberinya ruang sambil sesekali menanyakan kabarnya","s":4},{"t":"Mengabaikannya karena masalah pribadi bukan urusan tim","s":3},{"t":"Menegurnya karena menurunkan performa tim","s":2},{"t":"Menggosipkan keadaannya dengan anggota tim lain","s":1}],"ex":"Empati dan dukungan membantu rekan pulih sekaligus menjaga performa tim."},
{"id":"TKP-4568","q":"Seorang rekan dalam tim Anda sering membuat keputusan sendiri tanpa berkonsultasi dengan anggota lain. Cara terbaik adalah ....","opts":[{"t":"Mengingatkannya bahwa keputusan penting perlu dibahas bersama dalam tim","s":5},{"t":"Mengusulkan pembagian wewenang keputusan yang jelas dalam tim","s":4},{"t":"Membiarkannya karena keputusannya selama ini tepat","s":3},{"t":"Melakukan hal yang sama agar seimbang","s":2},{"t":"Menyabotase keputusannya agar ia jera","s":1}],"ex":"Kejelasan wewenang dan budaya konsultasi mencegah keputusan sepihak yang merugikan tim."},
{"id":"TKP-4569","q":"Rekan satu tim Anda cemburu karena Anda mendapat apresiasi atas kerja tim. Tindakan paling tepat adalah ....","opts":[{"t":"Berbagi apresiasi tersebut dengan seluruh anggota tim yang berkontribusi","s":5},{"t":"Menjelaskan kepadanya bahwa apresiasi itu untuk kerja seluruh tim","s":4},{"t":"Mengabaikan kecemburuannya karena bukan masalah Anda","s":3},{"t":"Menolak apresiasi tersebut agar ia tidak cemburu","s":2},{"t":"Menyombongkan apresiasi itu di depannya","s":1}],"ex":"Berbagi pengakuan dengan tim meredakan kecemburuan dan memperkuat kebersamaan."},
{"id":"TKP-4570","q":"Seorang rekan kerja meniru gaya dan ide Anda lalu mempresentasikannya sebagai miliknya dalam tim. Sikap terbaik adalah ....","opts":[{"t":"Tetap fokus berkontribusi dan mendokumentasikan ide-ide Anda secara tertulis","s":5},{"t":"Menegurnya secara pribadi dengan bukti yang jelas","s":4},{"t":"Membiarkannya karena ide yang baik memang untuk dipakai bersama","s":3},{"t":"Berhenti menyampaikan ide dalam tim","s":2},{"t":"Menuduhnya di depan seluruh anggota tim tanpa bukti","s":1}],"ex":"Dokumentasi ide melindungi karya Anda secara profesional tanpa konflik terbuka."},
{"id":"TKP-4571","q":"Rekan satu tim Anda enggan berbagi pengetahuan dan menyimpan informasi untuk dirinya sendiri. Cara terbaik adalah ....","opts":[{"t":"Membangun budaya berbagi dalam tim, misalnya sesi saling tukar pengetahuan rutin","s":5},{"t":"Meminta bantuannya secara spesifik saat Anda membutuhkan informasinya","s":4},{"t":"Mencari informasi sendiri tanpa melibatkannya","s":3},{"t":"Memaksanya membuka semua yang ia ketahui","s":2},{"t":"Menyembunyikan informasi Anda juga sebagai balasan","s":1}],"ex":"Budaya berbagi yang dibangun bersama mengubah perilaku lebih efektif daripada paksaan."},
{"id":"TKP-4572","q":"Seorang rekan dalam tim Anda mudah panik setiap ada masalah sehingga menulari anggota lain. Tindakan paling tepat adalah ....","opts":[{"t":"Tetap tenang, mengajak tim fokus pada solusi langkah demi langkah","s":5},{"t":"Menenangkannya secara pribadi sebelum membahas masalah dalam tim","s":4},{"t":"Membiarkannya panik karena itu reaksi alaminya","s":3},{"t":"Ikut panik agar ia merasa tidak sendirian","s":2},{"t":"Memarahinya karena mengganggu ketenangan tim","s":1}],"ex":"Ketenangan dan fokus pada solusi menular lebih kuat daripada kepanikan."},
{"id":"TKP-4573","q":"Rekan kerja Anda selalu pesimis dan meragukan setiap rencana tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendengarkan kekhawatirannya sebagai masukan risiko lalu mencari solusinya bersama","s":5},{"t":"Menunjukkan data dan contoh keberhasilan untuk membangun keyakinannya","s":4},{"t":"Mengabaikan komentar pesimisnya","s":3},{"t":"Mengeluarkannya dari pembahasan rencana tim","s":2},{"t":"Menertawakan sikap pesimisnya di depan tim","s":1}],"ex":"Mengolah kepesimisan menjadi identifikasi risiko justru memperkuat rencana tim."},
{"id":"TKP-4574","q":"Seorang rekan satu tim meminta kredit tambahan atas pekerjaan yang sebenarnya dikerjakan bersama. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan sistem pencatatan kontribusi yang transparan untuk seluruh tim","s":5},{"t":"Mendiskusikannya dengannya secara terbuka dan jujur","s":4},{"t":"Mengalah saja demi menjaga kedamaian tim","s":3},{"t":"Menuntut kredit yang sama besarnya","s":2},{"t":"Membocorkan masalah ini ke pimpinan tanpa bicara dulu dengannya","s":1}],"ex":"Sistem pencatatan yang transparan menyelesaikan perebutan kredit secara adil dan permanen."},
{"id":"TKP-4575","q":"Rekan kerja Anda sering menghilang saat jam kerja tim tanpa kabar yang jelas. Tindakan paling tepat adalah ....","opts":[{"t":"Menanyakan langsung kepadanya dan menyepakati aturan kehadiran dalam tim","s":5},{"t":"Mencatat ketidakhadirannya dan melaporkannya melalui mekanisme tim yang berlaku","s":4},{"t":"Membiarkannya karena mungkin ia punya urusan penting","s":3},{"t":"Menutupi ketidakhadirannya di depan koordinator","s":2},{"t":"Menyebarkan kabar bahwa ia malas bekerja","s":1}],"ex":"Komunikasi langsung dan aturan kehadiran yang jelas menyelesaikan masalah secara terbuka."}
,
{"id":"TKP-4576","q":"Dua anggota tim Anda mengklaim tugas yang sama sebagai tanggung jawabnya sehingga terjadi tumpang tindih pekerjaan. Tindakan paling tepat adalah ....","opts":[{"t":"Memfasilitasi pembahasan untuk memperjelas pembagian peran masing-masing dalam tim","s":5},{"t":"Membagi tugas tersebut menjadi dua bagian yang jelas untuk keduanya","s":4},{"t":"Menyerahkan tugas itu kepada salah satu dari mereka secara sepihak","s":3},{"t":"Membiarkan keduanya mengerjakannya agar hasilnya maksimal","s":2},{"t":"Mengambil alih tugas itu sendiri agar tidak ada yang ribut","s":1}],"ex":"Kejelasan peran yang dibahas bersama mencegah tumpang tindih dan konflik berulang."},
{"id":"TKP-4577","q":"Terjadi konflik antara dua rekan satu tim mengenai siapa yang berhak memimpin sebuah pekerjaan. Sikap terbaik Anda sebagai anggota tim adalah ....","opts":[{"t":"Mengusulkan kriteria kepemimpinan yang objektif lalu memutuskannya lewat musyawarah tim","s":5},{"t":"Menengahi keduanya dengan mendengarkan argumen masing-masing secara adil","s":4},{"t":"Mendukung salah satu yang lebih dekat dengan Anda","s":3},{"t":"Menjauhi konflik dan membiarkan mereka menyelesaikannya sendiri","s":2},{"t":"Mengambil alih kepemimpinan itu untuk diri sendiri","s":1}],"ex":"Kriteria objektif dan musyawarah menghasilkan keputusan yang diterima semua pihak."},
{"id":"TKP-4578","q":"Seorang rekan merasa tugas yang diberikan kepadanya tidak sesuai dengan kemampuannya. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mendiskusikan ulang pembagian tugas tim agar sesuai dengan kompetensi masing-masing","s":5},{"t":"Menawarkan bertukar tugas dengannya sesuai kemampuan","s":4},{"t":"Memintanya tetap mengerjakan karena itu keputusan bersama","s":3},{"t":"Mengabaikan keluhannya karena semua orang punya beban masing-masing","s":2},{"t":"Mengambil alih tugasnya agar ia tidak mengeluh lagi","s":1}],"ex":"Penyesuaian tugas berbasis kompetensi meningkatkan hasil dan kepuasan anggota tim."},
{"id":"TKP-4579","q":"Dalam tim Anda, batasan tanggung jawab tiap anggota tidak jelas sehingga pekerjaan penting terlewat. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan penyusunan matriks tanggung jawab yang disepakati seluruh tim","s":5},{"t":"Mengambil inisiatif mengerjakan pekerjaan yang terlewat sambil mengusulkan pembagian yang jelas","s":4},{"t":"Menunggu koordinator tim menyadari dan memperbaikinya","s":3},{"t":"Saling menuduh antar anggota tentang siapa yang lalai","s":2},{"t":"Membiarkan pekerjaan itu terlewat karena bukan tugas Anda","s":1}],"ex":"Matriks tanggung jawab yang jelas memastikan tidak ada pekerjaan yang terlewat."},
{"id":"TKP-4580","q":"Seorang rekan satu tim menolak bertanggung jawab atas kesalahan yang jelas-jelas bagiannya. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengajak tim mengevaluasi proses kerja agar kesalahan serupa tidak terulang","s":5},{"t":"Menunjukkan bukti secara pribadi kepadanya tanpa mempermalukannya","s":4},{"t":"Membiarkannya karena memaksa pengakuan hanya menimbulkan konflik","s":3},{"t":"Mempermalukannya di depan tim agar mau mengakui","s":2},{"t":"Mengambil alih tanggung jawabnya agar masalah cepat selesai","s":1}],"ex":"Evaluasi proses yang fokus pada perbaikan lebih produktif daripada memaksa pengakuan."},
{"id":"TKP-4581","q":"Dua tim kerja memperebutkan sumber daya yang sama untuk proyek masing-masing. Sebagai anggota salah satu tim, tindakan terbaik adalah ....","opts":[{"t":"Mengusulkan koordinasi antar tim untuk berbagi sumber daya secara adil dan terjadwal","s":5},{"t":"Mengajak perwakilan kedua tim bernegosiasi mencari solusi saling menguntungkan","s":4},{"t":"Berebut secepat mungkin agar tim Anda mendapat bagian lebih besar","s":3},{"t":"Menyerah dan membiarkan tim lain mengambil semuanya","s":2},{"t":"Menyembunyikan sumber daya agar tim lain tidak bisa menggunakannya","s":1}],"ex":"Koordinasi dan negosiasi antar tim menghasilkan pembagian sumber daya yang adil."},
{"id":"TKP-4582","q":"Seorang rekan menganggap pekerjaannya lebih penting daripada pekerjaan anggota tim lain. Cara terbaik adalah ....","opts":[{"t":"Mengingatkan bahwa setiap peran dalam tim sama pentingnya bagi keberhasilan bersama","s":5},{"t":"Menunjukkan bagaimana pekerjaannya saling bergantung dengan pekerjaan anggota lain","s":4},{"t":"Membiarkannya karena setiap orang berhak bangga dengan pekerjaannya","s":3},{"t":"Merendahkan pekerjaannya agar ia sadar","s":2},{"t":"Menuntut perlakuan istimewa juga untuk pekerjaan Anda","s":1}],"ex":"Kesadaran saling ketergantungan peran menumbuhkan penghargaan antar anggota tim."},
{"id":"TKP-4583","q":"Terjadi perselisihan dalam tim tentang prioritas pekerjaan yang harus diselesaikan lebih dulu. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak tim menyusun skala prioritas bersama berdasarkan urgensi dan dampak","s":5},{"t":"Mengusulkan voting untuk menentukan prioritas secara demokratis","s":4},{"t":"Mengikuti prioritas yang diinginkan anggota paling vokal","s":3},{"t":"Mengerjakan sesuai keinginan masing-masing tanpa kesepakatan","s":2},{"t":"Menunda semua pekerjaan sampai ada yang mengalah","s":1}],"ex":"Skala prioritas yang disusun bersama memberi acuan objektif bagi seluruh tim."},
{"id":"TKP-4584","q":"Seorang rekan satu tim melimpahkan kesalahannya kepada Anda di depan anggota tim lain. Sikap terbaik Anda adalah ....","opts":[{"t":"Menjelaskan fakta dengan tenang dan mengajak fokus pada solusi bersama","s":5},{"t":"Menyampaikan klarifikasi secara pribadi kepadanya setelah forum selesai","s":4},{"t":"Menerima saja tuduhannya demi menjaga keharmonisan","s":3},{"t":"Membalas menuduhnya di depan semua orang","s":2},{"t":"Menyimpan dendam dan membalas di lain waktu","s":1}],"ex":"Klarifikasi tenang berbasis fakta menjaga nama baik tanpa memperkeruh suasana tim."},
{"id":"TKP-4585","q":"Dalam tim Anda ada anggota yang mengerjakan tugas orang lain tanpa diminta sehingga menimbulkan kebingungan. Cara terbaik adalah ....","opts":[{"t":"Menegaskan kembali pembagian tugas dan jalur koordinasi dalam tim","s":5},{"t":"Mengapresiasi niat baiknya sambil menjelaskan pentingnya mengikuti pembagian peran","s":4},{"t":"Membiarkannya karena niatnya baik","s":3},{"t":"Melarangnya keras terlibat dalam tugas orang lain","s":2},{"t":"Mengadukannya sebagai pengacau kerja tim","s":1}],"ex":"Penegasan peran yang disertai apresiasi menjaga niat baik tanpa mengacaukan sistem."},
{"id":"TKP-4586","q":"Seorang rekan merasa ia selalu mendapat tugas tersulit dalam tim. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak tim meninjau ulang pembagian tugas agar beban terdistribusi adil","s":5},{"t":"Menawarkan bertukar tugas dengannya secara berkala","s":4},{"t":"Meyakinkannya bahwa itu tanda kepercayaan tim kepadanya","s":3},{"t":"Mengabaikannya karena semua tugas memang sulit","s":2},{"t":"Setuju saja agar ia berhenti mengeluh","s":1}],"ex":"Tinjauan ulang pembagian tugas memastikan keadilan beban kerja dalam tim."},
{"id":"TKP-4587","q":"Konflik peran terjadi karena dua anggota tim menerima perintah yang berbeda untuk pekerjaan yang sama. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan satu jalur komando yang jelas untuk penugasan dalam tim","s":5},{"t":"Mempertemukan keduanya untuk menyelaraskan pemahaman tugas","s":4},{"t":"Mengikuti salah satu perintah yang menurut Anda benar","s":3},{"t":"Mengerjakan dua-duanya agar aman","s":2},{"t":"Menolak mengerjakan keduanya sampai ada kejelasan","s":1}],"ex":"Satu jalur komando yang jelas mencegah perintah ganda dan konflik peran."},
{"id":"TKP-4588","q":"Seorang rekan satu tim ingin pindah ke tugas yang lebih ringan dengan alasan kelelahan. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mendiskusikan kondisinya dan mencari solusi bersama, misalnya rotasi tugas tim","s":5},{"t":"Menawarkan bantuan sementara sambil ia memulihkan kondisinya","s":4},{"t":"Menolak karena akan menambah beban anggota lain","s":3},{"t":"Membiarkannya pindah tanpa pembahasan","s":2},{"t":"Menuduhnya malas dan tidak solid","s":1}],"ex":"Rotasi tugas dan diskusi terbuka menyeimbangkan kebutuhan individu dan tim."},
{"id":"TKP-4589","q":"Dalam tim Anda, seorang anggota sering mengambil keputusan yang seharusnya menjadi wewenang bersama. Tindakan paling tepat adalah ....","opts":[{"t":"Menyepakati batas wewenang individu dan keputusan yang harus dibahas bersama","s":5},{"t":"Mengingatkannya secara baik-baik setiap ia melampaui wewenangnya","s":4},{"t":"Membiarkannya selama keputusannya tidak merugikan","s":3},{"t":"Melakukan hal yang sama agar seimbang","s":2},{"t":"Mengancam akan melaporkannya","s":1}],"ex":"Batas wewenang yang disepakati melindungi keputusan kolektif tim."},
{"id":"TKP-4590","q":"Seorang rekan merasa kontribusinya tidak dihargai dalam tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan mekanisme apresiasi kontribusi dalam tim secara rutin","s":5},{"t":"Menyampaikan penghargaan secara tulus atas kontribusinya","s":4},{"t":"Meyakinkannya bahwa semua orang merasakan hal yang sama","s":3},{"t":"Mengabaikannya karena penghargaan bukan tujuan bekerja","s":2},{"t":"Menyindirnya karena terlalu haus pujian","s":1}],"ex":"Mekanisme apresiasi yang rutin membuat setiap anggota merasa dihargai."},
{"id":"TKP-4591","q":"Terjadi perebutan peran sebagai juru bicara tim dalam sebuah kegiatan. Cara terbaik menyelesaikannya adalah ....","opts":[{"t":"Menentukan juru bicara lewat musyawarah berdasarkan kemampuan komunikasi","s":5},{"t":"Mengusulkan peran bergilir agar semua mendapat kesempatan","s":4},{"t":"Menunjuk yang paling senior secara otomatis","s":3},{"t":"Membiarkan keduanya tampil bersamaan","s":2},{"t":"Membatalkan keikutsertaan tim dalam kegiatan itu","s":1}],"ex":"Penunjukan berbasis kemampuan lewat musyawarah menghasilkan perwakilan terbaik tim."},
{"id":"TKP-4592","q":"Seorang rekan satu tim bekerja melampaui perannya hingga mengganggu area kerja anggota lain. Tindakan paling tepat adalah ....","opts":[{"t":"Mendiskusikan batas peran masing-masing agar inisiatifnya tersalurkan tepat","s":5},{"t":"Mengapresiasi semangatnya sambil menjelaskan pembagian area kerja","s":4},{"t":"Membiarkannya karena semangat kerja patut didukung","s":3},{"t":"Menegurnya dengan keras agar tidak mencampuri urusan orang","s":2},{"t":"Melaporkannya sebagai pelanggar aturan tim","s":1}],"ex":"Penyaluran inisiatif sesuai batas peran menjaga semangat tanpa mengganggu orang lain."},
{"id":"TKP-4593","q":"Dalam tim Anda, tidak ada yang mau menjadi penanggung jawab sebuah tugas berisiko. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan pembagian tanggung jawab bersama dengan dukungan penuh tim","s":5},{"t":"Menawarkan diri menjadi penanggung jawab dengan syarat tim mendukung penuh","s":4},{"t":"Menunggu sampai ada yang berani maju","s":3},{"t":"Menolak tugas berisiko itu secara kolektif","s":2},{"t":"Menunjuk seseorang secara paksa","s":1}],"ex":"Tanggung jawab kolektif dengan dukungan tim membuat tugas berisiko bisa dijalankan."},
{"id":"TKP-4594","q":"Seorang rekan menyalahkan pembagian tugas yang tidak adil setiap tim gagal mencapai target. Cara terbaik adalah ....","opts":[{"t":"Mengajak tim mengevaluasi pembagian tugas dan faktor kegagalan secara objektif","s":5},{"t":"Mendengarkan keluhannya dan mengusulkan perbaikan pembagian tugas","s":4},{"t":"Membiarkannya mengeluh karena mungkin memang ada yang tidak adil","s":3},{"t":"Menyalahkannya balik karena tidak bekerja maksimal","s":2},{"t":"Menghindari satu tim dengannya agar tidak disalahkan","s":1}],"ex":"Evaluasi objektif memisahkan masalah pembagian tugas dari faktor kegagalan lain."},
{"id":"TKP-4595","q":"Dua anggota tim berselisih karena gaya komunikasi yang berbeda, satu blak-blakan satu sensitif. Tindakan paling tepat adalah ....","opts":[{"t":"Memfasilitasi dialog agar keduanya saling memahami gaya komunikasi masing-masing","s":5},{"t":"Menyepakati etika berkomunikasi yang disepakati seluruh tim","s":4},{"t":"Meminta yang blak-blakan untuk selalu mengalah","s":3},{"t":"Membiarkan karena itu masalah kepribadian","s":2},{"t":"Memisahkan keduanya agar tidak perlu berkomunikasi","s":1}],"ex":"Saling memahami gaya komunikasi mencegah salah paham menjadi konflik."},
{"id":"TKP-4596","q":"Seorang rekan satu tim mengabaikan kesepakatan pembagian tugas yang sudah dibuat bersama. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengingatkannya pada kesepakatan dan mendiskusikan hambatan yang ia hadapi","s":5},{"t":"Mengusulkan peninjauan kesepakatan bila kondisinya memang berubah","s":4},{"t":"Mengabaikan pelanggarannya demi menghindari konflik","s":3},{"t":"Menghukumnya dengan tidak melibatkannya lagi","s":2},{"t":"Melanggar kesepakatan juga sebagai balasan","s":1}],"ex":"Mengingatkan kesepakatan sambil memahami hambatan menegakkan aturan tanpa konflik."},
{"id":"TKP-4597","q":"Dalam tim Anda terjadi konflik karena perbedaan cara menyelesaikan pekerjaan yang sudah mendesak. Cara terbaik adalah ....","opts":[{"t":"Mengajak tim memilih metode tercepat yang disepakati bersama untuk kondisi darurat","s":5},{"t":"Menggabungkan kelebihan kedua cara menjadi solusi kompromi","s":4},{"t":"Memaksakan satu cara agar cepat selesai","s":3},{"t":"Membiarkan masing-masing memakai caranya sendiri","s":2},{"t":"Menunda pekerjaan sampai konflik selesai","s":1}],"ex":"Kesepakatan metode darurat mengutamakan penyelesaian tanpa mengorbankan kebersamaan."},
{"id":"TKP-4598","q":"Seorang rekan merasa perannya dalam tim tidak penting dibandingkan peran anggota lain. Tindakan paling tepat adalah ....","opts":[{"t":"Menunjukkan bagaimana perannya berkontribusi pada keberhasilan tim secara keseluruhan","s":5},{"t":"Memberinya tanggung jawab yang lebih terlihat dalam proyek berikutnya","s":4},{"t":"Meyakinkannya bahwa semua peran memang sama saja","s":3},{"t":"Mengabaikannya karena itu hanya perasaan","s":2},{"t":"Setuju bahwa perannya memang kurang penting","s":1}],"ex":"Menunjukkan kontribusi nyata setiap peran membangun rasa berarti dalam tim."},
{"id":"TKP-4599","q":"Terjadi konflik dalam tim karena informasi tugas yang diterima tiap anggota berbeda-beda. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan satu sumber informasi resmi dan mekanisme konfirmasi dalam tim","s":5},{"t":"Mengumpulkan semua versi informasi lalu menyelaraskannya bersama","s":4},{"t":"Mengikuti informasi yang Anda terima saja","s":3},{"t":"Menyalahkan penyampai informasi yang berbeda-beda","s":2},{"t":"Berhenti bekerja sampai informasinya seragam","s":1}],"ex":"Satu sumber informasi resmi mencegah konflik akibat perbedaan pemahaman tugas."},
{"id":"TKP-4600","q":"Seorang rekan satu tim menuntut perlakuan khusus karena masa kerjanya paling lama. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menegaskan bahwa hak dan kewajiban dalam tim berlaku sama dengan penghargaan pada pengalaman","s":5},{"t":"Menghormati pengalamannya sambil menjelaskan aturan tim yang adil","s":4},{"t":"Memberinya perlakuan khusus agar tidak ribut","s":3},{"t":"Mengabaikan tuntutannya sama sekali","s":2},{"t":"Menuntut perlakuan khusus juga untuk diri sendiri","s":1}],"ex":"Keadilan aturan yang disertai penghargaan pengalaman menyeimbangkan senioritas dan kesetaraan."}
,
{"id":"TKP-4601","q":"Tim Anda harus berkoordinasi dengan unit lain yang jadwalnya selalu penuh sehingga sulit ditemui. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajukan jadwal koordinasi jauh hari dengan agenda yang jelas dan efisien","s":5},{"t":"Menyesuaikan waktu pertemuan dengan ketersediaan unit tersebut","s":4},{"t":"Memaksa mereka meluangkan waktu karena pekerjaan tim Anda penting","s":3},{"t":"Bekerja tanpa koordinasi agar tidak terhambat","s":2},{"t":"Melaporkan unit tersebut sebagai penghambat pekerjaan","s":1}],"ex":"Koordinasi yang terjadwal dengan agenda jelas menghargai waktu semua pihak."},
{"id":"TKP-4602","q":"Terjadi miskomunikasi antara tim Anda dan tim dari unit lain mengenai pembagian pekerjaan bersama. Sikap terbaik adalah ....","opts":[{"t":"Mengadakan pertemuan penyelarasan untuk memperjelas pembagian tugas kedua tim","s":5},{"t":"Menyusun dokumen kesepakatan tertulis tentang peran masing-masing tim","s":4},{"t":"Menyalahkan tim lain yang tidak memahami pembagian","s":3},{"t":"Mengerjakan seluruhnya sendiri agar tidak ribet","s":2},{"t":"Menarik tim Anda dari pekerjaan bersama itu","s":1}],"ex":"Penyelarasan dan kesepakatan tertulis mencegah miskomunikasi antar tim terulang."},
{"id":"TKP-4603","q":"Unit lain meminta bantuan tim Anda di saat tim Anda sendiri sedang sibuk. Tindakan paling tepat adalah ....","opts":[{"t":"Mendiskusikan prioritas dan kapasitas tim lalu menyepakati bentuk bantuan yang realistis","s":5},{"t":"Memberikan bantuan sebatas yang tidak mengganggu tugas utama tim","s":4},{"t":"Menolak mentah-mentah karena tim sendiri sibuk","s":3},{"t":"Mengorbankan tugas tim demi membantu unit lain","s":2},{"t":"Berjanji membantu tapi tidak menepatinya","s":1}],"ex":"Bantuan yang realistis sesuai kapasitas menjaga kewajiban tim sekaligus solidaritas antar unit."},
{"id":"TKP-4604","q":"Tim Anda dan tim lain memiliki cara kerja yang berbeda dalam proyek gabungan. Cara terbaik adalah ....","opts":[{"t":"Menyepakati standar kerja bersama yang mengakomodasi kedua tim","s":5},{"t":"Mengadakan lokakarya penyamaan persepsi di awal proyek","s":4},{"t":"Memaksa tim lain mengikuti cara kerja tim Anda","s":3},{"t":"Membiarkan masing-masing bekerja dengan caranya","s":2},{"t":"Memisahkan proyek menjadi dua bagian yang tidak terhubung","s":1}],"ex":"Standar kerja bersama yang disepakati menyatukan perbedaan tanpa dominasi."},
{"id":"TKP-4605","q":"Koordinasi dengan unit lain terhambat karena tidak ada narahubung yang jelas. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan penunjukan narahubung resmi dari masing-masing pihak","s":5},{"t":"Berinisiatif menjadi penghubung sementara sambil menunggu penunjukan resmi","s":4},{"t":"Berhenti berkoordinasi sampai ada narahubung resmi","s":3},{"t":"Menghubungi siapa saja yang dikenal di unit tersebut","s":2},{"t":"Menyalahkan unit lain yang tidak menyiapkan narahubung","s":1}],"ex":"Narahubung resmi memperlancar koordinasi dan memperjelas tanggung jawab komunikasi."},
{"id":"TKP-4606","q":"Unit lain mengubah kesepakatan kerjasama secara sepihak tanpa pemberitahuan. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak berdialog untuk memahami alasannya dan menegosiasikan ulang kesepakatan","s":5},{"t":"Mengingatkan kesepakatan tertulis yang sudah dibuat bersama","s":4},{"t":"Membalas mengubah kesepakatan secara sepihak juga","s":3},{"t":"Menerima saja perubahan itu tanpa protes","s":2},{"t":"Memutus kerja sama dan melaporkan mereka","s":1}],"ex":"Dialog dan negosiasi ulang menyelesaikan perubahan sepihak secara profesional."},
{"id":"TKP-4607","q":"Tim Anda membutuhkan data dari unit lain, tetapi proses permintaannya berbelit-belit. Cara terbaik adalah ....","opts":[{"t":"Mengikuti prosedur resmi sambil membangun komunikasi baik dengan petugas terkait","s":5},{"t":"Mengajukan permintaan resmi dengan melampirkan urgensi kebutuhan tim","s":4},{"t":"Meminta tolong orang dalam agar proses dipercepat","s":3},{"t":"Mengambil data tanpa prosedur resmi","s":2},{"t":"Menyerah dan bekerja tanpa data tersebut","s":1}],"ex":"Prosedur resmi yang didukung komunikasi baik menghasilkan data tanpa melanggar aturan."},
{"id":"TKP-4608","q":"Dalam proyek tim lintas unit, terjadi saling lempar tanggung jawab saat ada masalah. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan pembagian tanggung jawab tertulis yang jelas sejak awal proyek","s":5},{"t":"Mengambil inisiatif menyelesaikan masalah sambil mengklarifikasi peran","s":4},{"t":"Ikut melempar tanggung jawab agar tim Anda tidak disalahkan","s":3},{"t":"Membiarkan masalah berlarut tanpa penyelesaian","s":2},{"t":"Menuduh unit lain sebagai penyebab masalah","s":1}],"ex":"Pembagian tanggung jawab tertulis mencegah saling lempar saat masalah muncul."},
{"id":"TKP-4609","q":"Unit lain menilai tim Anda lambat dalam merespons koordinasi. Tindakan paling tepat adalah ....","opts":[{"t":"Mengevaluasi alur respons tim dan menetapkan batas waktu respons yang disepakati","s":5},{"t":"Menjelaskan kendala tim Anda dan menyepakati ekspektasi yang realistis","s":4},{"t":"Membela diri bahwa tim Anda sudah bekerja maksimal","s":3},{"t":"Mengabaikan penilaian mereka","s":2},{"t":"Balik menilai mereka juga lambat","s":1}],"ex":"Evaluasi alur respons dan ekspektasi realistis memperbaiki koordinasi antar unit."},
{"id":"TKP-4610","q":"Tim Anda diminta bergabung dalam tim gabungan dengan anggota dari berbagai unit yang belum saling kenal. Sikap terbaik adalah ....","opts":[{"t":"Aktif berkenalan dan membangun kerja sama yang terbuka sejak awal","s":5},{"t":"Mengusulkan sesi perkenalan dan pembagian peran di awal pembentukan tim","s":4},{"t":"Bersikap pasif menunggu orang lain memulai","s":3},{"t":"Hanya berinteraksi dengan anggota dari unit sendiri","s":2},{"t":"Menolak bergabung karena tidak kenal anggotanya","s":1}],"ex":"Inisiatif membangun keakraban sejak awal mempercepat kekompakan tim gabungan."},
{"id":"TKP-4611","q":"Terjadi perbedaan prioritas antara tim Anda dan unit mitra dalam proyek bersama. Cara terbaik adalah ....","opts":[{"t":"Menyelaraskan prioritas lewat diskusi dengan mempertimbangkan kepentingan bersama","s":5},{"t":"Mencari titik temu dengan mengorbankan sebagian prioritas masing-masing","s":4},{"t":"Memaksakan prioritas tim Anda karena lebih penting","s":3},{"t":"Menjalankan proyek dengan dua prioritas berbeda","s":2},{"t":"Menghentikan proyek bersama tersebut","s":1}],"ex":"Penyelarasan prioritas lewat diskusi menjaga proyek bersama tetap berjalan."},
{"id":"TKP-4612","q":"Unit mitra sering membatalkan jadwal koordinasi secara mendadak. Tindakan paling tepat adalah ....","opts":[{"t":"Mendiskusikan penyebabnya dan menyepakati komitmen jadwal yang realistis","s":5},{"t":"Menyiapkan agenda alternatif yang bisa dibahas tanpa pertemuan tatap muka","s":4},{"t":"Memarahi mereka setiap ada pembatalan","s":3},{"t":"Berhenti mengajak mereka berkoordinasi","s":2},{"t":"Melaporkan mereka ke pimpinan masing-masing","s":1}],"ex":"Memahami penyebab dan komitmen realistis lebih efektif daripada sekadar protes."},
{"id":"TKP-4613","q":"Tim Anda menerima informasi yang berbeda dari dua unit mitra mengenai tugas yang sama. Sikap terbaik adalah ....","opts":[{"t":"Mengonfirmasi langsung ke sumber resmi dan menyelaraskan informasi ke semua pihak","s":5},{"t":"Mengadakan pertemuan klarifikasi dengan kedua unit mitra","s":4},{"t":"Mengikuti informasi yang paling menguntungkan tim Anda","s":3},{"t":"Menyalahkan kedua unit yang memberi info berbeda","s":2},{"t":"Menunda pekerjaan sampai informasinya jelas sendiri","s":1}],"ex":"Konfirmasi ke sumber resmi dan klarifikasi bersama menyelesaikan perbedaan informasi."},
{"id":"TKP-4614","q":"Dalam koordinasi lintas unit, usulan tim Anda selalu ditolak tanpa penjelasan. Cara terbaik adalah ....","opts":[{"t":"Meminta penjelasan dan masukan agar usulan berikutnya lebih dapat diterima","s":5},{"t":"Menyusun usulan dengan data yang lebih kuat dan presentasi yang lebih baik","s":4},{"t":"Berhenti mengajukan usulan sama sekali","s":3},{"t":"Menuduh unit lain tidak menghargai tim Anda","s":2},{"t":"Memaksakan usulan dengan ancaman","s":1}],"ex":"Meminta masukan dan memperkuat usulan mengubah penolakan menjadi perbaikan."},
{"id":"TKP-4615","q":"Unit lain meminta tim Anda mengubah hasil kerja yang sudah disepakati bersama. Tindakan paling tepat adalah ....","opts":[{"t":"Mendiskusikan alasan perubahan dan menegosiasikan solusi yang adil bagi kedua pihak","s":5},{"t":"Meninjau kembali kesepakatan dan menilai kelayakan perubahan yang diminta","s":4},{"t":"Menolak mentah-mentah karena sudah disepakati","s":3},{"t":"Mengubahnya tanpa diskusi agar cepat selesai","s":2},{"t":"Mengubahnya asal-asalan sebagai protes","s":1}],"ex":"Negosiasi berbasis alasan menjaga kesepakatan sekaligus fleksibilitas kerja sama."},
{"id":"TKP-4616","q":"Koordinasi proyek gabungan terhambat karena perbedaan istilah teknis antar unit. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan glosarium istilah bersama yang dipakai seluruh tim gabungan","s":5},{"t":"Menanyakan arti istilah yang tidak dipahami setiap kali muncul kebingungan","s":4},{"t":"Berpura-pura paham agar tidak terlihat bodoh","s":3},{"t":"Memaksa unit lain memakai istilah tim Anda","s":2},{"t":"Mengabaikan perbedaan istilah itu","s":1}],"ex":"Glosarium bersama menghilangkan hambatan komunikasi akibat perbedaan istilah."},
{"id":"TKP-4617","q":"Tim Anda ditugaskan memimpin koordinasi proyek yang melibatkan banyak unit. Tindakan pertama yang paling tepat adalah ....","opts":[{"t":"Menyusun rencana kerja dan pembagian peran yang jelas lalu disepakati semua unit","s":5},{"t":"Mengadakan pertemuan awal untuk menyamakan visi dan ekspektasi","s":4},{"t":"Langsung membagi tugas tanpa diskusi agar cepat","s":3},{"t":"Menunggu unit lain mengajukan rencana mereka","s":2},{"t":"Menolak memimpin karena terlalu berat","s":1}],"ex":"Rencana dan peran yang disepakati di awal menjadi fondasi koordinasi banyak unit."},
{"id":"TKP-4618","q":"Salah satu unit mitra tidak mengirimkan perwakilannya dalam rapat koordinasi penting. Cara terbaik adalah ....","opts":[{"t":"Menghubungi mereka untuk menanyakan kendalanya dan menjadwalkan ulang bila perlu","s":5},{"t":"Membagikan hasil rapat secara tertulis agar mereka tetap terinformasi","s":4},{"t":"Mengambil keputusan tanpa melibatkan mereka","s":3},{"t":"Memarahi mereka di forum berikutnya","s":2},{"t":"Mengeluarkan mereka dari proyek gabungan","s":1}],"ex":"Komunikasi proaktif dan berbagi hasil menjaga keterlibatan unit yang absen."},
{"id":"TKP-4619","q":"Terjadi tumpang tindih kewenangan antara tim Anda dan unit lain dalam sebuah kegiatan. Sikap terbaik adalah ....","opts":[{"t":"Mendiskusikan dan membagi kewenangan secara jelas lewat kesepakatan tertulis","s":5},{"t":"Mengusulkan pembagian area kerja berdasarkan kompetensi masing-masing","s":4},{"t":"Berebut kewenangan agar tim Anda dominan","s":3},{"t":"Menyerahkan seluruh kewenangan kepada unit lain","s":2},{"t":"Bekerja sendiri-sendiri tanpa koordinasi","s":1}],"ex":"Pembagian kewenangan tertulis yang jelas mengakhiri tumpang tindih secara permanen."},
{"id":"TKP-4620","q":"Unit mitra meminta tim Anda menyelesaikan pekerjaan mereka yang tertunda. Tindakan paling tepat adalah ....","opts":[{"t":"Menilai kapasitas tim lalu menyepakati bantuan yang tidak mengorbankan tugas utama","s":5},{"t":"Membantu sebagian sambil menetapkan batas waktu yang jelas","s":4},{"t":"Menolak karena itu bukan tanggung jawab tim Anda","s":3},{"t":"Mengambil alih seluruhnya demi menjaga hubungan baik","s":2},{"t":"Membantu tapi dengan setengah hati","s":1}],"ex":"Bantuan terukur sesuai kapasitas menjaga tugas utama sekaligus solidaritas."},
{"id":"TKP-4621","q":"Dalam proyek gabungan, unit mitra tidak transparan mengenai progres pekerjaan tim. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan mekanisme pelaporan progres berkala yang berlaku untuk semua unit","s":5},{"t":"Menanyakan progresnya secara rutin dengan cara yang sopan","s":4},{"t":"Membiarkannya karena itu urusan internal mereka","s":3},{"t":"Menuduh mereka menyembunyikan kegagalan","s":2},{"t":"Memata-matai pekerjaan mereka","s":1}],"ex":"Mekanisme pelaporan berkala menciptakan transparansi tanpa kecurigaan."},
{"id":"TKP-4622","q":"Tim Anda dan unit lain berbeda pendapat tentang target proyek bersama. Sikap terbaik Anda adalah ....","opts":[{"t":"Menyepakati target yang realistis berdasarkan data dan kemampuan bersama","s":5},{"t":"Mengusulkan target bertahap yang bisa dievaluasi bersama","s":4},{"t":"Memaksakan target versi tim Anda","s":3},{"t":"Mengikuti target unit lain tanpa diskusi","s":2},{"t":"Menarik diri dari proyek karena tidak sepakat","s":1}],"ex":"Target realistis berbasis data yang disepakati memberi arah jelas bagi semua pihak."},
{"id":"TKP-4623","q":"Koordinasi dengan unit lain sering gagal karena pesan tidak sampai ke orang yang tepat. Tindakan paling tepat adalah ....","opts":[{"t":"Menetapkan alur komunikasi resmi dengan penanggung jawab di tiap unit","s":5},{"t":"Mengonfirmasi penerimaan setiap pesan penting yang dikirim","s":4},{"t":"Mengirim pesan berulang-ulang sampai ada respons","s":3},{"t":"Menyalahkan mereka yang tidak membaca pesan","s":2},{"t":"Berhenti mengirim informasi penting","s":1}],"ex":"Alur komunikasi resmi dengan penanggung jawab memastikan pesan sampai ke tujuan."},
{"id":"TKP-4624","q":"Unit mitra mengusulkan perubahan jadwal proyek yang merugikan tim Anda. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mendiskusikan dampaknya dan mencari jadwal alternatif yang adil bagi semua","s":5},{"t":"Menyampaikan keberatan disertai data dampak terhadap tim Anda","s":4},{"t":"Menerima saja demi menjaga hubungan baik","s":3},{"t":"Menolak keras tanpa mau berdiskusi","s":2},{"t":"Menyabotase jadwal baru tersebut","s":1}],"ex":"Diskusi dampak dan alternatif adil menyelesaikan konflik jadwal secara profesional."},
{"id":"TKP-4625","q":"Setelah proyek gabungan tim selesai, unit mitra tidak mau ikut mengevaluasi hasilnya. Sikap terbaik Anda adalah ....","opts":[{"t":"Menyusun evaluasi dari sisi tim Anda dan membagikannya sebagai bahan pembelajaran bersama","s":5},{"t":"Mengundang mereka sekali lagi dengan menekankan manfaat evaluasi","s":4},{"t":"Membiarkannya karena evaluasi bukan kewajiban","s":3},{"t":"Menyalahkan mereka atas kegagalan yang tidak dievaluasi","s":2},{"t":"Memalsukan hasil evaluasi seolah mereka ikut","s":1}],"ex":"Berbagi hasil evaluasi tetap memberi manfaat pembelajaran meski mitra tidak ikut."}
,
{"id":"TKP-4626","q":"Dalam musyawarah tim, dua pendapat yang sama kuat tidak mencapai kata sepakat. Tindakan paling tepat adalah ....","opts":[{"t":"Mencari alternatif ketiga yang mengakomodasi kepentingan kedua belah pihak","s":5},{"t":"Menunda keputusan sambil menggali informasi tambahan","s":4},{"t":"Memaksakan salah satu pendapat dengan voting","s":3},{"t":"Membiarkan musyawarah berlarut tanpa keputusan","s":2},{"t":"Membubarkan tim karena tidak bisa sepakat","s":1}],"ex":"Alternatif ketiga yang mengakomodasi semua pihak adalah esensi musyawarah mufakat."},
{"id":"TKP-4627","q":"Seorang anggota tim menolak hasil musyawarah karena pendapatnya tidak dipakai. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengingatkannya bahwa musyawarah mengikat semua anggota meski pendapatnya berbeda","s":5},{"t":"Menjelaskan kembali alasan keputusan musyawarah secara pribadi kepadanya","s":4},{"t":"Membiarkannya menolak karena itu haknya","s":3},{"t":"Mengubah hasil musyawarah agar ia senang","s":2},{"t":"Mengeluarkannya dari tim karena tidak taat kesepakatan","s":1}],"ex":"Hasil musyawarah mengikat semua pihak; penjelasan personal membantu menerima keputusan."},
{"id":"TKP-4628","q":"Musyawarah tim Anda selalu didominasi segelintir orang yang vokal. Cara terbaik adalah ....","opts":[{"t":"Menerapkan tata cara musyawarah yang memberi kesempatan bicara merata","s":5},{"t":"Meminta pendapat anggota yang pendiam secara bergiliran","s":4},{"t":"Membiarkannya karena yang vokal biasanya paling paham","s":3},{"t":"Melarang yang vokal berbicara","s":2},{"t":"Berhenti ikut musyawarah","s":1}],"ex":"Tata cara yang merata memastikan semua suara terdengar dalam musyawarah."},
{"id":"TKP-4629","q":"Keputusan musyawarah tim ternyata keliru setelah dijalankan. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak tim mengevaluasi dan memperbaiki keputusan lewat musyawarah ulang","s":5},{"t":"Mengakui kekeliruan bersama dan mencari solusi perbaikan","s":4},{"t":"Menyalahkan pengusul keputusan tersebut","s":3},{"t":"Menyembunyikan kekeliruan agar tim tidak malu","s":2},{"t":"Membubarkan tim dan membentuk yang baru","s":1}],"ex":"Musyawarah ulang untuk memperbaiki keputusan menunjukkan kedewasaan tim."},
{"id":"TKP-4630","q":"Seorang anggota tim tidak hadir dalam musyawarah penting lalu protes terhadap hasilnya. Sikap terbaik Anda adalah ....","opts":[{"t":"Menjelaskan hasil musyawarah dan mengajaknya menghormati keputusan bersama","s":5},{"t":"Membagikan notulen musyawarah agar ia memahami prosesnya","s":4},{"t":"Mengulang musyawarah dari awal demi dirinya","s":3},{"t":"Mengabaikan protesnya sama sekali","s":2},{"t":"Membatalkan hasil musyawarah tersebut","s":1}],"ex":"Keputusan musyawarah tetap berlaku; notulen membantu yang absen memahami proses."},
{"id":"TKP-4631","q":"Dalam musyawarah, seorang anggota memaksakan kehendaknya dengan emosi. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Tetap tenang, mengajak kembali ke pokok bahasan dan aturan musyawarah","s":5},{"t":"Memberinya waktu menenangkan diri sebelum melanjutkan","s":4},{"t":"Mengikuti kehendaknya agar suasana cepat reda","s":3},{"t":"Membalas dengan emosi yang sama","s":2},{"t":"Mengusirnya dari forum musyawarah","s":1}],"ex":"Ketenangan dan kembali ke aturan menjaga musyawarah tetap produktif."},
{"id":"TKP-4632","q":"Tim Anda harus mengambil keputusan cepat padahal musyawarah belum mencapai mufakat. Tindakan paling tepat adalah ....","opts":[{"t":"Menyepakati mekanisme keputusan darurat yang sudah dibahas sebelumnya","s":5},{"t":"Mengambil keputusan sementara yang bisa ditinjau kembali","s":4},{"t":"Menunggu mufakat meski tenggat terlewat","s":3},{"t":"Membiarkan satu orang memutuskan sepihak","s":2},{"t":"Tidak mengambil keputusan apa pun","s":1}],"ex":"Mekanisme darurat yang disepakati memungkinkan keputusan cepat tanpa melanggar prinsip."},
{"id":"TKP-4633","q":"Hasil musyawarah tim bertentangan dengan keinginan pribadi Anda. Sikap terbaik Anda adalah ....","opts":[{"t":"Menerima dan melaksanakan hasil musyawarah dengan penuh komitmen","s":5},{"t":"Menyampaikan keberatan secara resmi lalu tetap mengikuti keputusan","s":4},{"t":"Melaksanakan setengah hati sambil berharap gagal","s":3},{"t":"Menolak melaksanakan hasil musyawarah","s":2},{"t":"Menghasut anggota lain untuk menolak juga","s":1}],"ex":"Komitmen pada hasil musyawarah adalah wujud kedewasaan berorganisasi."},
{"id":"TKP-4634","q":"Seorang anggota tim selalu abstain dalam setiap pengambilan keputusan. Cara terbaik adalah ....","opts":[{"t":"Mengajaknya berdiskusi untuk memahami alasannya dan mendorong partisipasinya","s":5},{"t":"Menjelaskan bahwa setiap anggota tim punya tanggung jawab ikut memutuskan","s":4},{"t":"Membiarkannya abstain karena itu haknya","s":3},{"t":"Menghitung abstain sebagai penolakan","s":2},{"t":"Mengeluarkannya dari proses pengambilan keputusan","s":1}],"ex":"Memahami alasan dan mendorong partisipasi mengaktifkan anggota yang pasif."},
{"id":"TKP-4635","q":"Musyawarah tim Anda buntu karena masing-masing mempertahankan egonya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajak semua pihak fokus pada kepentingan tim, bukan kemenangan pribadi","s":5},{"t":"Mengusulkan jeda dan melanjutkan dengan kepala dingin","s":4},{"t":"Memihak salah satu agar cepat selesai","s":3},{"t":"Membiarkan kebuntuan berlarut","s":2},{"t":"Mengambil keputusan sendiri tanpa musyawarah","s":1}],"ex":"Fokus pada kepentingan bersama melunakkan ego dalam musyawarah."},
{"id":"TKP-4636","q":"Keputusan penting tim harus diambil tetapi data pendukungnya belum lengkap. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengambil keputusan terbaik berdasarkan data yang ada dengan catatan untuk ditinjau ulang","s":5},{"t":"Mengumpulkan data tambahan secepatnya sambil menyiapkan opsi keputusan","s":4},{"t":"Menunda keputusan sampai data benar-benar lengkap","s":3},{"t":"Mengambil keputusan asal-asalan","s":2},{"t":"Melempar keputusan kepada pihak lain","s":1}],"ex":"Keputusan berbasis data tersedia dengan tinjauan ulang menyeimbangkan kecepatan dan kehati-hatian."},
{"id":"TKP-4637","q":"Seorang anggota baru tim mempertanyakan hasil musyawarah yang dibuat sebelum ia bergabung. Cara terbaik adalah ....","opts":[{"t":"Menjelaskan latar belakang keputusan dan mengajaknya berkontribusi ke depan","s":5},{"t":"Membagikan notulen musyawarah sebelumnya kepadanya","s":4},{"t":"Menyuruhnya menerima saja tanpa penjelasan","s":3},{"t":"Mengulang seluruh musyawarah dari awal","s":2},{"t":"Mengabaikan pertanyaannya","s":1}],"ex":"Penjelasan latar belakang membantu anggota baru memahami dan menghormati keputusan."},
{"id":"TKP-4638","q":"Dalam musyawarah tim, muncul usulan yang bagus tetapi di luar kewenangan tim. Tindakan paling tepat adalah ....","opts":[{"t":"Mencatat usulan tersebut dan meneruskannya ke pihak yang berwenang","s":5},{"t":"Mengapresiasi usulan dan membahas bagian yang masih dalam kewenangan tim","s":4},{"t":"Menolak langsung karena di luar kewenangan","s":3},{"t":"Melaksanakan usulan itu meski di luar kewenangan","s":2},{"t":"Menertawakan pengusulnya","s":1}],"ex":"Meneruskan usulan baik ke pihak berwenang menghargai ide tanpa melanggar kewenangan."},
{"id":"TKP-4639","q":"Tim Anda terbelah menjadi dua kubu yang saling tidak mau mengalah dalam musyawarah. Sikap terbaik Anda adalah ....","opts":[{"t":"Bertindak sebagai penengah yang netral dan mencari solusi saling menguntungkan","s":5},{"t":"Mengusulkan kompromi yang mengakomodasi kepentingan kedua kubu","s":4},{"t":"Bergabung dengan kubu yang lebih kuat","s":3},{"t":"Membiarkan perpecahan berlarut","s":2},{"t":"Memperkeruh suasana agar satu kubu menyerah","s":1}],"ex":"Penengah netral yang mencari solusi saling menguntungkan menyatukan kembali tim."},
{"id":"TKP-4640","q":"Hasil musyawarah tim tidak dilaksanakan oleh sebagian anggota. Tindakan paling tepat adalah ....","opts":[{"t":"Mengevaluasi hambatan pelaksanaan dan memperkuat komitmen bersama","s":5},{"t":"Mengingatkan kembali kesepakatan dan konsekuensinya","s":4},{"t":"Membiarkannya karena pelaksanaan adalah urusan masing-masing","s":3},{"t":"Melaksanakan sendiri seluruh hasil musyawarah","s":2},{"t":"Membatalkan hasil musyawarah tersebut","s":1}],"ex":"Evaluasi hambatan dan penguatan komitmen memastikan hasil musyawarah terlaksana."},
{"id":"TKP-4641","q":"Seorang anggota tim mengusulkan voting untuk setiap keputusan kecil agar cepat. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menyepakati jenis keputusan yang bisa diputus cepat dan yang perlu musyawarah mendalam","s":5},{"t":"Menjelaskan bahwa musyawarah tetap utama untuk keputusan penting","s":4},{"t":"Setuju voting untuk semua keputusan","s":3},{"t":"Menolak mentah-mentah usulannya","s":2},{"t":"Membiarkan tim terpecah soal metode","s":1}],"ex":"Klasifikasi jenis keputusan menyeimbangkan kecepatan dan kualitas musyawarah."},
{"id":"TKP-4642","q":"Dalam musyawarah, fakta yang disampaikan seorang anggota ternyata keliru. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengoreksi dengan data yang benar secara sopan tanpa mempermalukannya","s":5},{"t":"Menanyakan sumber datanya untuk verifikasi bersama","s":4},{"t":"Membiarkannya karena tidak enak mengoreksi","s":3},{"t":"Menertawakannya di depan forum","s":2},{"t":"Menggunakan kekeliruannya untuk mendiskreditkannya","s":1}],"ex":"Koreksi sopan berbasis data menjaga kualitas keputusan tanpa melukai anggota."},
{"id":"TKP-4643","q":"Tim Anda harus bermusyawarah tentang hal sensitif yang melibatkan salah satu anggota. Tindakan paling tepat adalah ....","opts":[{"t":"Membahas dengan bijak tanpa menyebut nama dan fokus pada penyelesaian masalah","s":5},{"t":"Meminta anggota yang bersangkutan tidak hadir saat pembahasan","s":4},{"t":"Membatalkannya karena terlalu sensitif","s":3},{"t":"Membahasnya secara terbuka dengan menyebut nama","s":2},{"t":"Menyebarkan masalah sensitif itu ke luar tim","s":1}],"ex":"Pembahasan bijak yang menjaga privasi menyelesaikan masalah sensitif secara etis."},
{"id":"TKP-4644","q":"Seorang anggota tim mendominasi musyawarah dengan banyak bicara tetapi sedikit substansi. Cara terbaik adalah ....","opts":[{"t":"Mengarahkan diskusi dengan tata tertib bicara yang fokus pada substansi","s":5},{"t":"Meminta setiap pembicara menyampaikan poin pentingnya secara ringkas","s":4},{"t":"Membiarkannya bicara selama yang ia mau","s":3},{"t":"Memotong pembicaraannya dengan kasar","s":2},{"t":"Tidak mengundangnya dalam musyawarah berikutnya","s":1}],"ex":"Tata tertib yang fokus substansi membuat musyawarah efisien dan adil."},
{"id":"TKP-4645","q":"Keputusan musyawarah tim Anda ditentang oleh pihak luar tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Menjelaskan dasar keputusan tim secara profesional dan membuka dialog","s":5},{"t":"Mengevaluasi kembali keputusan dengan mempertimbangkan masukan pihak luar","s":4},{"t":"Bersikeras tanpa mau mendengar","s":3},{"t":"Langsung mengubah keputusan sesuai keinginan pihak luar","s":2},{"t":"Bermusuhan dengan pihak luar tersebut","s":1}],"ex":"Penjelasan profesional disertai keterbukaan evaluasi menjaga wibawa tim."},
{"id":"TKP-4646","q":"Dalam musyawarah tim, tidak ada yang berani menyampaikan pendapat berbeda dengan mayoritas. Tindakan paling tepat adalah ....","opts":[{"t":"Mendorong budaya aman berpendapat dan meminta pandangan yang berbeda secara khusus","s":5},{"t":"Menyampaikan sendiri pendapat berbeda sebagai contoh","s":4},{"t":"Membiarkannya karena keseragaman itu baik","s":3},{"t":"Memaksa seseorang menyampaikan pendapat berbeda","s":2},{"t":"Menganggap musyawarah sudah berhasil","s":1}],"ex":"Budaya aman berpendapat mencegah groupthink dan meningkatkan kualitas keputusan."},
{"id":"TKP-4647","q":"Seorang anggota tim mengancam keluar jika keputusannya tidak dipakai dalam musyawarah. Cara terbaik adalah ....","opts":[{"t":"Tetap pada prinsip musyawarah sambil membujuknya menghargai proses bersama","s":5},{"t":"Mendengarkan alasannya dengan serius sebelum memutuskan","s":4},{"t":"Mengikuti keputusannya agar ia tidak keluar","s":3},{"t":"Mempersilakan keluar tanpa pembahasan","s":2},{"t":"Mengancam balik dengan sanksi","s":1}],"ex":"Keteguhan prinsip disertai bujukan menjaga integritas musyawarah dan keutuhan tim."},
{"id":"TKP-4648","q":"Musyawarah tim Anda menghasilkan keputusan yang sulit dilaksanakan di lapangan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan penyesuaian teknis lewat musyawarah lanjutan tanpa mengubah semangat keputusan","s":5},{"t":"Melaporkan kendala lapangan secara jujur kepada tim","s":4},{"t":"Melaksanakan asal-asalan saja","s":3},{"t":"Mengabaikan keputusan itu diam-diam","s":2},{"t":"Menyalahkan perumus keputusan","s":1}],"ex":"Penyesuaian teknis lewat musyawarah menjaga keputusan tetap bisa dilaksanakan."},
{"id":"TKP-4649","q":"Tim Anda perlu bermusyawarah tetapi anggotanya tersebar dan sulit berkumpul. Tindakan paling tepat adalah ....","opts":[{"t":"Menyelenggarakan musyawarah dengan mekanisme yang memungkinkan partisipasi jarak jauh","s":5},{"t":"Mengumpulkan aspirasi tertulis lalu membahasnya dalam forum terbatas perwakilan","s":4},{"t":"Menunda musyawarah sampai semua bisa berkumpul","s":3},{"t":"Memutuskan sendiri tanpa musyawarah","s":2},{"t":"Membatalkan pembahasan tersebut","s":1}],"ex":"Mekanisme partisipasi jarak jauh memastikan musyawarah tetap inklusif."},
{"id":"TKP-4650","q":"Seorang anggota tim selalu menuntut musyawarah diulang setiap ada hal kecil yang berubah. Cara terbaik adalah ....","opts":[{"t":"Menyepakati batasan hal yang perlu musyawarah ulang dan yang cukup pemberitahuan","s":5},{"t":"Menjelaskan bahwa perubahan kecil bisa disesuaikan tanpa musyawarah penuh","s":4},{"t":"Mengulang musyawarah setiap ia menuntut","s":3},{"t":"Menolak semua tuntutannya tanpa penjelasan","s":2},{"t":"Mengeluarkannya dari tim","s":1}],"ex":"Batasan yang disepakati menjaga musyawarah efisien tanpa mengabaikan aspirasi."}
,
{"id":"TKP-4651","q":"Rapat tim Anda sering molor tanpa hasil yang jelas. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan agenda rapat yang jelas dengan batas waktu tiap pembahasan","s":5},{"t":"Menunjuk notulis dan penanggung jawab tindak lanjut setiap rapat","s":4},{"t":"Mempercepat rapat dengan memotong semua pembicaraan","s":3},{"t":"Berhenti menghadiri rapat yang tidak efektif","s":2},{"t":"Membiarkannya karena rapat memang selalu begitu","s":1}],"ex":"Agenda jelas dan tindak lanjut yang tercatat membuat rapat produktif."},
{"id":"TKP-4652","q":"Seorang anggota tim selalu bermain ponsel saat rapat berlangsung. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan aturan rapat yang disepakati, termasuk fokus penuh selama rapat","s":5},{"t":"Menegurnya secara pribadi dengan cara yang baik","s":4},{"t":"Membiarkannya karena mungkin ada urusan penting","s":3},{"t":"Ikut bermain ponsel juga","s":2},{"t":"Menyita ponselnya saat rapat","s":1}],"ex":"Aturan fokus yang disepakati bersama menjaga efektivitas rapat tanpa konflik."},
{"id":"TKP-4653","q":"Rapat tim Anda dihadiri terlalu banyak orang sehingga tidak efektif. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan pembatasan peserta sesuai relevansi agenda rapat","s":5},{"t":"Membagi rapat menjadi sesi pleno dan sesi teknis","s":4},{"t":"Membiarkannya karena semakin banyak semakin baik","s":3},{"t":"Melarang sebagian orang hadir secara sepihak","s":2},{"t":"Tidak mengadakan rapat sama sekali","s":1}],"ex":"Peserta yang relevan dan pembagian sesi membuat rapat tepat sasaran."},
{"id":"TKP-4654","q":"Hasil rapat tim sering tidak ditindaklanjuti oleh anggotanya. Tindakan paling tepat adalah ....","opts":[{"t":"Menetapkan penanggung jawab dan tenggat untuk setiap keputusan rapat","s":5},{"t":"Membagikan notulen rapat dan memantau progres tindak lanjutnya","s":4},{"t":"Mengulang pembahasan yang sama di rapat berikutnya","s":3},{"t":"Membiarkannya karena tindak lanjut urusan masing-masing","s":2},{"t":"Berhenti membuat keputusan dalam rapat","s":1}],"ex":"Penanggung jawab dan tenggat yang jelas memastikan hasil rapat terlaksana."},
{"id":"TKP-4655","q":"Seorang anggota tim tidak pernah membaca bahan rapat yang dibagikan sebelumnya. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengingatkan pentingnya persiapan dan menyepakati mekanisme berbagi bahan yang efektif","s":5},{"t":"Menyampaikan ringkasan bahan di awal rapat secara singkat","s":4},{"t":"Membiarkannya karena membaca bahan adalah urusan pribadi","s":3},{"t":"Mempermalukannya di depan peserta rapat","s":2},{"t":"Berhenti membagikan bahan rapat","s":1}],"ex":"Pengingat dan mekanisme berbagi yang efektif meningkatkan kesiapan peserta rapat."},
{"id":"TKP-4656","q":"Rapat tim Anda selalu dimulai terlambat karena menunggu anggota yang belum datang. Cara terbaik adalah ....","opts":[{"t":"Menyepakati dan menerapkan aturan mulai tepat waktu bagi seluruh tim","s":5},{"t":"Memulai rapat tepat waktu dengan peserta yang hadir","s":4},{"t":"Terus menunggu sampai semua anggota datang","s":3},{"t":"Membatalkan rapat setiap ada yang terlambat","s":2},{"t":"Ikut datang terlambat juga","s":1}],"ex":"Aturan mulai tepat waktu yang konsisten mendisiplinkan seluruh anggota."},
{"id":"TKP-4657","q":"Dalam rapat, pembahasan sering melenceng jauh dari agenda. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkan dengan sopan untuk kembali ke agenda yang disepakati","s":5},{"t":"Menunjuk moderator rapat yang tegas menjaga agenda","s":4},{"t":"Membiarkan pembahasan melenceng agar semua puas","s":3},{"t":"Meninggalkan rapat saat pembahasan melenceng","s":2},{"t":"Memarahi yang menyebabkan pembahasan melenceng","s":1}],"ex":"Moderator dan pengingat sopan menjaga rapat tetap pada agenda."},
{"id":"TKP-4658","q":"Seorang anggota tim memonopoli waktu bicara dalam rapat. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan pembatasan waktu bicara yang adil untuk setiap peserta","s":5},{"t":"Memberinya isyarat halus saat waktunya sudah cukup","s":4},{"t":"Membiarkannya karena ia banyak ide","s":3},{"t":"Berteriak memintanya diam","s":2},{"t":"Tidak mengundangnya ke rapat berikutnya","s":1}],"ex":"Pembatasan waktu bicara yang adil memberi ruang bagi semua peserta."},
{"id":"TKP-4659","q":"Rapat tim Anda tidak pernah menghasilkan notulen sehingga keputusan mudah dilupakan. Cara terbaik adalah ....","opts":[{"t":"Menunjuk notulis tetap dan membagikan notulen setelah setiap rapat","s":5},{"t":"Menawarkan diri menjadi notulis secara bergiliran dengan anggota lain","s":4},{"t":"Mengandalkan ingatan masing-masing peserta","s":3},{"t":"Merekam rapat tanpa sepengetahuan peserta","s":2},{"t":"Berhenti mengadakan rapat","s":1}],"ex":"Notulen yang dibagikan menjadi acuan resmi hasil dan tindak lanjut rapat."},
{"id":"TKP-4660","q":"Seorang anggota tim selalu mengusulkan rapat untuk hal-hal sepele. Tindakan paling tepat adalah ....","opts":[{"t":"Menyepakati kriteria hal yang perlu rapat dan yang cukup dibahas biasa","s":5},{"t":"Menyarankan alternatif pembahasan yang lebih efisien untuk hal sepele","s":4},{"t":"Mengikuti semua usul rapatnya","s":3},{"t":"Menolak semua usul rapatnya","s":2},{"t":"Mengejeknya karena terlalu suka rapat","s":1}],"ex":"Kriteria yang jelas mencegah rapat berlebihan untuk hal sepele."},
{"id":"TKP-4661","q":"Peserta rapat tim Anda terlihat mengantuk dan tidak fokus. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan rapat yang singkat, terjadwal baik, dan diselingi jeda","s":5},{"t":"Membuat suasana rapat lebih interaktif dengan melibatkan peserta","s":4},{"t":"Membiarkannya karena itu masalah pribadi","s":3},{"t":"Membangunkannya dengan cara memalukan","s":2},{"t":"Mengeluarkan yang mengantuk dari rapat","s":1}],"ex":"Rapat singkat yang interaktif menjaga fokus dan energi peserta."},
{"id":"TKP-4662","q":"Dalam rapat tim, terjadi perdebatan sengit yang tidak kunjung selesai. Cara terbaik adalah ....","opts":[{"t":"Menengahi dengan merangkum perbedaan dan mengusulkan jalan tengah","s":5},{"t":"Mengusulkan penundaan dengan tugas menggali data pendukung","s":4},{"t":"Membiarkan perdebatan sampai ada yang menyerah","s":3},{"t":"Memihak salah satu pihak yang berdebat","s":2},{"t":"Membubarkan rapat dengan emosi","s":1}],"ex":"Penengah yang merangkum dan mengusulkan jalan tengah menyelesaikan perdebatan."},
{"id":"TKP-4663","q":"Seorang anggota tim tidak pernah menyampaikan progresnya dalam rapat evaluasi. Tindakan paling tepat adalah ....","opts":[{"t":"Menanyakan progresnya dengan cara mendukung dan menawarkan bantuan bila terkendala","s":5},{"t":"Menyepakati format pelaporan progres yang wajib diisi semua anggota","s":4},{"t":"Membiarkannya karena mungkin tidak ada progres","s":3},{"t":"Memaksanya bicara dengan ancaman","s":2},{"t":"Melaporkannya sebagai anggota tidak produktif","s":1}],"ex":"Pendekatan mendukung dan format pelaporan jelas mendorong keterbukaan progres."},
{"id":"TKP-4664","q":"Rapat tim Anda sering dihadiri orang yang tidak berkepentingan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan daftar undangan rapat berdasarkan relevansi agenda","s":5},{"t":"Menanyakan perannya dalam rapat secara sopan","s":4},{"t":"Membiarkannya karena menambah ramai","s":3},{"t":"Mengusirnya dari ruang rapat","s":2},{"t":"Membocorkan informasi rapat agar ia jera","s":1}],"ex":"Daftar undangan berbasis relevansi menjaga rapat tetap fokus dan efisien."},
{"id":"TKP-4665","q":"Keputusan rapat tim Anda sering berubah-ubah di setiap pertemuan. Cara terbaik adalah ....","opts":[{"t":"Menegaskan komitmen pada keputusan dan mencatat alasan setiap perubahan","s":5},{"t":"Mengevaluasi mengapa keputusan sering berubah lalu memperbaikinya","s":4},{"t":"Membiarkannya karena fleksibilitas itu baik","s":3},{"t":"Menolak semua perubahan keputusan","s":2},{"t":"Berhenti mengikuti keputusan rapat","s":1}],"ex":"Komitmen dan pencatatan alasan perubahan menjaga konsistensi keputusan rapat."},
{"id":"TKP-4666","q":"Seorang anggota tim mengkritik cara Anda memimpin rapat di depan peserta lain. Tindakan paling tepat adalah ....","opts":[{"t":"Menerima kritik dengan terbuka dan mengajaknya memberi saran perbaikan","s":5},{"t":"Mendiskusikannya setelah rapat untuk memahami maksudnya","s":4},{"t":"Membela diri dengan emosi di depan peserta","s":3},{"t":"Mengabaikan kritiknya sama sekali","s":2},{"t":"Membalas mengkritiknya di depan semua orang","s":1}],"ex":"Keterbukaan terhadap kritik memperbaiki kualitas kepemimpinan rapat."},
{"id":"TKP-4667","q":"Rapat tim Anda selalu melebihi waktu yang direncanakan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan manajemen waktu rapat yang ketat dengan penjaga waktu","s":5},{"t":"Memprioritaskan agenda penting di awal rapat","s":4},{"t":"Membiarkannya karena pembahasan penting butuh waktu","s":3},{"t":"Keluar rapat saat waktunya habis","s":2},{"t":"Mempercepat dengan memotong semua pembicaraan","s":1}],"ex":"Manajemen waktu dan prioritas agenda menjaga rapat selesai tepat waktu."},
{"id":"TKP-4668","q":"Dalam rapat, seorang anggota tim menyampaikan ide yang menurut Anda kurang tepat. Cara terbaik adalah ....","opts":[{"t":"Mengapresiasi idenya lalu mendiskusikan kekurangannya secara konstruktif","s":5},{"t":"Menanyakan detail idenya untuk memahami maksudnya lebih dulu","s":4},{"t":"Langsung menolak idenya di depan forum","s":3},{"t":"Menertawakan idenya","s":2},{"t":"Mengabaikan idenya sama sekali","s":1}],"ex":"Apresiasi dan diskusi konstruktif menjaga semangat berinovasi dalam tim."},
{"id":"TKP-4669","q":"Tim Anda jarang mengadakan rapat sehingga koordinasi antar anggota lemah. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan jadwal rapat rutin yang disepakati dengan agenda jelas","s":5},{"t":"Berinisiatif mengadakan pertemuan koordinasi berkala","s":4},{"t":"Membiarkannya karena rapat membuang waktu","s":3},{"t":"Bekerja sendiri-sendiri tanpa koordinasi","s":2},{"t":"Memaksa rapat setiap hari","s":1}],"ex":"Rapat rutin terjadwal dengan agenda jelas memperkuat koordinasi tim."},
{"id":"TKP-4670","q":"Seorang anggota tim membocorkan isi rapat internal ke pihak luar. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengingatkan pentingnya kerahasiaan dan menyepakati etika rapat bersama","s":5},{"t":"Menegurnya secara pribadi dengan bukti yang jelas","s":4},{"t":"Membiarkannya karena informasi akan tersebar juga","s":3},{"t":"Menyebarkan kabar tentang perbuatannya","s":2},{"t":"Berhenti membahas hal penting dalam rapat","s":1}],"ex":"Etika kerahasiaan yang disepakati melindungi kepercayaan dalam tim."},
{"id":"TKP-4671","q":"Rapat tim Anda didominasi pembahasan administratif yang membosankan. Cara terbaik adalah ....","opts":[{"t":"Memisahkan pembahasan administratif dan substantif ke forum yang berbeda","s":5},{"t":"Menyampaikan hal administratif lewat dokumen tertulis sebelum rapat","s":4},{"t":"Membiarkannya karena administratif juga penting","s":3},{"t":"Menolak membahas administratif sama sekali","s":2},{"t":"Tidur saat pembahasan administratif","s":1}],"ex":"Pemisahan forum membuat rapat substantif tetap hidup dan fokus."},
{"id":"TKP-4672","q":"Seorang anggota tim selalu datang tanpa persiapan ke rapat. Tindakan paling tepat adalah ....","opts":[{"t":"Menyepakati standar persiapan rapat dan mengingatkan secara konsisten","s":5},{"t":"Mengirimkan bahan dan ekspektasi persiapan jauh hari sebelumnya","s":4},{"t":"Membiarkannya karena persiapan urusan pribadi","s":3},{"t":"Mempermalukannya setiap ia tidak siap","s":2},{"t":"Mengeluarkannya dari daftar peserta","s":1}],"ex":"Standar persiapan yang disepakati dan konsisten meningkatkan kualitas rapat."},
{"id":"TKP-4673","q":"Dalam rapat tim, Anda tidak setuju dengan keputusan yang diambil mayoritas. Sikap terbaik Anda adalah ....","opts":[{"t":"Menyampaikan ketidaksetujuan secara resmi lalu tetap menghormati keputusan","s":5},{"t":"Meminta dicatat sebagai catatan keberatan dalam notulen","s":4},{"t":"Menolak melaksanakan keputusan tersebut","s":3},{"t":"Menghasut anggota lain untuk menolak","s":2},{"t":"Keluar dari tim sebagai protes","s":1}],"ex":"Keberatan resmi yang tercatat menghormati proses sekaligus posisi Anda."},
{"id":"TKP-4674","q":"Rapat tim Anda sering diganggu interupsi dari luar. Cara terbaik adalah ....","opts":[{"t":"Menyepakati aturan anti-interupsi selama rapat berlangsung","s":5},{"t":"Menunjuk penjaga pintu atau pengatur jadwal tamu saat rapat","s":4},{"t":"Membiarkan interupsi karena mungkin penting","s":3},{"t":"Memarahi setiap pengganggu","s":2},{"t":"Memindahkan rapat ke tempat tersembunyi","s":1}],"ex":"Aturan anti-interupsi melindungi fokus dan efektivitas rapat."},
{"id":"TKP-4675","q":"Setelah rapat selesai, anggota tim memiliki pemahaman berbeda tentang hasilnya. Tindakan paling tepat adalah ....","opts":[{"t":"Membagikan notulen dan meminta konfirmasi pemahaman dari semua anggota","s":5},{"t":"Merangkum ulang keputusan di akhir setiap rapat","s":4},{"t":"Membiarkannya karena masing-masing pasti paham","s":3},{"t":"Menyalahkan notulis yang tidak jelas","s":2},{"t":"Mengulang rapat dari awal","s":1}],"ex":"Rangkuman akhir dan konfirmasi notulen menyamakan pemahaman hasil rapat."}
,
{"id":"TKP-4676","q":"Anda diberi wewenang mendelegasikan tugas dalam tim, tetapi khawatir hasilnya tidak maksimal. Tindakan paling tepat adalah ....","opts":[{"t":"Mendelegasikan dengan penjelasan jelas, tenggat, dan pemantauan berkala","s":5},{"t":"Mendelegasikan tugas ringan dulu sambil menilai kemampuannya","s":4},{"t":"Mengerjakan semuanya sendiri agar hasilnya terjamin","s":3},{"t":"Mendelegasikan tanpa penjelasan apa pun","s":2},{"t":"Menolak wewenang delegasi tersebut","s":1}],"ex":"Delegasi dengan penjelasan dan pemantauan menyeimbangkan kepercayaan dan kualitas."},
{"id":"TKP-4677","q":"Seorang anggota tim menolak tugas yang Anda delegasikan kepadanya. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendiskusikan alasannya dan mencari solusi, misalnya penyesuaian beban","s":5},{"t":"Menjelaskan pentingnya tugas itu bagi keberhasilan tim","s":4},{"t":"Memaksanya menerima dengan ancaman sanksi","s":3},{"t":"Membatalkan delegasi dan mengerjakan sendiri","s":2},{"t":"Memberikan tugas itu kepada orang lain sambil menyindirnya","s":1}],"ex":"Diskusi alasan penolakan menghasilkan solusi tanpa paksaan."},
{"id":"TKP-4678","q":"Hasil tugas yang Anda delegasikan kepada rekan satu tim ternyata jauh dari harapan. Cara terbaik adalah ....","opts":[{"t":"Mengevaluasi bersama letak kekurangannya dan memberi bimbingan perbaikan","s":5},{"t":"Memberinya kesempatan memperbaiki dengan arahan yang lebih jelas","s":4},{"t":"Mengambil alih dan tidak pernah mendelegasikan lagi kepadanya","s":3},{"t":"Memarahinya di depan tim","s":2},{"t":"Menyembunyikan hasil buruknya dari tim","s":1}],"ex":"Evaluasi dan bimbingan mengubah kegagalan delegasi menjadi pembelajaran."},
{"id":"TKP-4679","q":"Dalam tim Anda, pembagian tugas selalu menumpuk pada orang yang sama. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan rotasi dan pemerataan tugas yang disepakati tim","s":5},{"t":"Menawarkan diri mengambil sebagian beban yang menumpuk","s":4},{"t":"Membiarkannya karena ia memang paling mampu","s":3},{"t":"Menambah beban orang lain secara paksa","s":2},{"t":"Mengeluhkan ketidakadilan tanpa solusi","s":1}],"ex":"Rotasi dan pemerataan yang disepakati mencegah kelelahan dan ketidakadilan."},
{"id":"TKP-4680","q":"Seorang rekan satu tim mengerjakan tugas delegasi dengan cara yang berbeda dari instruksi Anda. Sikap terbaik Anda adalah ....","opts":[{"t":"Menilai hasilnya; bila baik, diskusikan perbedaannya sebagai pembelajaran","s":5},{"t":"Menanyakan alasannya memakai cara berbeda sebelum menilai","s":4},{"t":"Menolak hasilnya karena tidak sesuai instruksi","s":3},{"t":"Memarahinya karena tidak patuh","s":2},{"t":"Membiarkannya tanpa evaluasi","s":1}],"ex":"Fokus pada hasil dengan diskusi terbuka menghargai inisiatif sekaligus standar."},
{"id":"TKP-4681","q":"Anda menerima delegasi tugas dari rekan satu tim yang menurut Anda di luar kemampuan Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menyampaikan keterbatasan Anda secara jujur dan meminta bimbingan","s":5},{"t":"Menerimanya sambil belajar dan meminta pendampingan rekan","s":4},{"t":"Menolak mentah-mentah tanpa penjelasan","s":3},{"t":"Menerimanya lalu mengerjakannya asal-asalan","s":2},{"t":"Melimpahkan diam-diam kepada orang lain","s":1}],"ex":"Kejujuran tentang keterbatasan disertai kemauan belajar membangun kepercayaan."},
{"id":"TKP-4682","q":"Seorang anggota tim mendelegasikan kembali tugasnya kepada orang lain tanpa sepengetahuan tim. Cara terbaik adalah ....","opts":[{"t":"Menegaskan aturan bahwa delegasi ulang harus sepengetahuan dan persetujuan tim","s":5},{"t":"Mendiskusikan alasannya melakukan delegasi ulang","s":4},{"t":"Membiarkannya selama pekerjaan selesai","s":3},{"t":"Melarang keras segala bentuk delegasi ulang","s":2},{"t":"Melaporkannya sebagai pelanggaran berat","s":1}],"ex":"Aturan delegasi ulang yang jelas menjaga akuntabilitas dalam tim."},
{"id":"TKP-4683","q":"Dalam tim Anda tidak ada yang berani menerima delegasi tugas sulit. Sikap terbaik Anda adalah ....","opts":[{"t":"Memecah tugas sulit menjadi bagian kecil dan mendelegasikannya bertahap dengan pendampingan","s":5},{"t":"Menawarkan diri mengambil bagian tersulit sebagai contoh","s":4},{"t":"Memaksa seseorang menerimanya","s":3},{"t":"Membiarkan tugas sulit itu terbengkalai","s":2},{"t":"Mengerjakannya sendiri sambil mengeluh","s":1}],"ex":"Pemecahan tugas dan pendampingan membuat delegasi sulit bisa diterima."},
{"id":"TKP-4684","q":"Seorang rekan satu tim merasa tugas yang didelegasikan kepadanya terlalu mudah dan meremehkan. Tindakan paling tepat adalah ....","opts":[{"t":"Menjelaskan kontribusi tugas itu bagi tim dan memberinya tantangan tambahan","s":5},{"t":"Menawarkan tugas yang lebih menantang sesuai kemampuannya","s":4},{"t":"Membiarkannya meremehkan asal selesai","s":3},{"t":"Menegurnya karena tidak menghargai tugas","s":2},{"t":"Mencabut delegasi dan memberikannya kepada orang lain","s":1}],"ex":"Penjelasan kontribusi dan tantangan sesuai kemampuan menjaga motivasi."},
{"id":"TKP-4685","q":"Anda mendelegasikan tugas tetapi rekan tersebut terus bertanya hal-hal sepele. Cara terbaik adalah ....","opts":[{"t":"Memberikan panduan tertulis yang lengkap sejak awal delegasi","s":5},{"t":"Menjawab dengan sabar sambil melatih kemandiriannya bertahap","s":4},{"t":"Memintanya berhenti bertanya dan berpikir sendiri","s":3},{"t":"Mengambil kembali tugas itu","s":2},{"t":"Mengabaikan pertanyaannya","s":1}],"ex":"Panduan lengkap dan latihan kemandirian mengurangi ketergantungan bertahap."},
{"id":"TKP-4686","q":"Pembagian tugas dalam tim Anda diputuskan sepihak tanpa melibatkan anggota. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan pembahasan pembagian tugas secara partisipatif dalam tim","s":5},{"t":"Menyampaikan masukan tentang pembagian yang lebih adil","s":4},{"t":"Menerima saja tanpa protes","s":3},{"t":"Menolak mengerjakan tugas yang diputuskan sepihak","s":2},{"t":"Menghasut anggota lain untuk menolak","s":1}],"ex":"Pembagian tugas partisipatif meningkatkan penerimaan dan keadilan."},
{"id":"TKP-4687","q":"Seorang anggota tim menyelesaikan tugas delegasi lebih cepat dan meminta tugas tambahan. Tindakan paling tepat adalah ....","opts":[{"t":"Mengapresiasinya dan mendelegasikan tugas tambahan sesuai kapasitasnya","s":5},{"t":"Memintanya membantu rekan yang kesulitan","s":4},{"t":"Membiarkannya bersantai karena sudah selesai","s":3},{"t":"Menambah bebannya berlebihan sebagai hukuman kecepatan","s":2},{"t":"Mencurigainya mengerjakan asal-asalan","s":1}],"ex":"Apresiasi dan delegasi tambahan proporsional menghargai kinerja unggul."},
{"id":"TKP-4688","q":"Dalam tim Anda, tugas penting selalu diberikan kepada anggota yang itu-itu saja. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan pemerataan kesempatan tugas penting untuk pengembangan semua anggota","s":5},{"t":"Menawarkan diri mengambil tugas penting berikutnya","s":4},{"t":"Membiarkannya karena mereka memang paling dipercaya","s":3},{"t":"Memprotes dengan keras","s":2},{"t":"Menarik diri dari tim","s":1}],"ex":"Pemerataan kesempatan mengembangkan kapasitas seluruh anggota tim."},
{"id":"TKP-4689","q":"Seorang rekan satu tim tidak melaporkan progres tugas delegasinya hingga tenggat tiba. Sikap terbaik Anda adalah ....","opts":[{"t":"Menetapkan mekanisme pelaporan progres berkala sejak awal delegasi","s":5},{"t":"Menanyakan progresnya secara rutin dengan cara yang tidak menekan","s":4},{"t":"Menunggu sampai tenggat tanpa menanyakan","s":3},{"t":"Memarahinya saat tenggat terlewat","s":2},{"t":"Tidak pernah mendelegasikan lagi kepadanya","s":1}],"ex":"Pelaporan berkala sejak awal mencegah kejutan di tenggat akhir."},
{"id":"TKP-4690","q":"Anda diminta mendelegasikan tugas tim tetapi tidak diberi wewenang yang jelas. Tindakan paling tepat adalah ....","opts":[{"t":"Meminta kejelasan wewenang tertulis sebelum melakukan delegasi","s":5},{"t":"Mendelegasikan sebatas yang Anda yakini dalam wewenang Anda","s":4},{"t":"Mendelegasikan semuanya tanpa wewenang jelas","s":3},{"t":"Menolak melakukan delegasi","s":2},{"t":"Mengarang wewenang sendiri","s":1}],"ex":"Kejelasan wewenang tertulis menjadi dasar delegasi yang sah."},
{"id":"TKP-4691","q":"Seorang anggota tim cemburu karena tidak mendapat delegasi tugas bergengsi. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menjelaskan kriteria delegasi secara transparan dan memberinya kesempatan berikutnya","s":5},{"t":"Menawarkan tugas lain yang sesuai dengan kemampuannya","s":4},{"t":"Membiarkannya cemburu karena itu masalah pribadinya","s":3},{"t":"Memberinya tugas bergengsi itu juga agar adil","s":2},{"t":"Mengejek kecemburuannya","s":1}],"ex":"Transparansi kriteria dan kesempatan berikutnya meredakan kecemburuan."},
{"id":"TKP-4692","q":"Dalam tim Anda, delegasi tugas sering tidak disertai tenggat yang jelas. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan setiap delegasi disertai tenggat dan prioritas yang jelas","s":5},{"t":"Menanyakan tenggat setiap menerima delegasi tugas","s":4},{"t":"Mengerjakan sesuai kecepatan sendiri","s":3},{"t":"Menunda sampai ditagih","s":2},{"t":"Menolak tugas tanpa tenggat","s":1}],"ex":"Tenggat yang jelas pada setiap delegasi menjaga ritme kerja tim."},
{"id":"TKP-4693","q":"Seorang rekan satu tim mengklaim tidak pernah menerima delegasi tugas dari Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Mendokumentasikan setiap delegasi secara tertulis ke depannya","s":5},{"t":"Mengonfirmasi ulang pemahaman tugas bersamanya","s":4},{"t":"Berdebat tentang siapa yang benar","s":3},{"t":"Mengerjakan tugas itu sendiri","s":2},{"t":"Menuduhnya berbohong","s":1}],"ex":"Dokumentasi tertulis mencegah sengketa delegasi di masa depan."},
{"id":"TKP-4694","q":"Tim Anda kekurangan personel sehingga pembagian tugas sangat berat. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan prioritas tugas dan penyesuaian target sesuai kapasitas tim","s":5},{"t":"Mengajukan permohonan tambahan personel atau dukungan","s":4},{"t":"Memaksa tim bekerja lembur terus-menerus","s":3},{"t":"Membiarkan tugas terbengkalai","s":2},{"t":"Menyalahkan kondisi kekurangan personel","s":1}],"ex":"Prioritas dan penyesuaian target realistis menjaga tim tetap berfungsi."},
{"id":"TKP-4695","q":"Seorang anggota tim mengerjakan tugas delegasi dengan kualitas asal-asalan. Sikap terbaik Anda adalah ....","opts":[{"t":"Memberi umpan balik jujur dan membimbingnya meningkatkan kualitas","s":5},{"t":"Menunjukkan standar kualitas yang diharapkan dengan contoh","s":4},{"t":"Menerima hasilnya apa adanya","s":3},{"t":"Mempermalukannya di depan tim","s":2},{"t":"Tidak pernah melibatkannya lagi","s":1}],"ex":"Umpan balik jujur dan contoh standar memperbaiki kualitas secara membangun."},
{"id":"TKP-4696","q":"Dalam tim Anda, ada anggota yang hanya mau mengerjakan tugas yang disukainya. Tindakan paling tepat adalah ....","opts":[{"t":"Menegaskan komitmen tim bahwa pembagian tugas berdasarkan kebutuhan, bukan kesukaan","s":5},{"t":"Mendiskusikan motivasinya dan mencari titik temu","s":4},{"t":"Membiarkannya memilih tugas sesukanya","s":3},{"t":"Memberinya hanya tugas yang tidak disukai sebagai hukuman","s":2},{"t":"Mengeluarkannya dari tim","s":1}],"ex":"Komitmen pada kebutuhan tim menyeimbangkan preferensi pribadi anggota."},
{"id":"TKP-4697","q":"Anda menerima banyak delegasi tugas dari berbagai rekan satu tim hingga kewalahan. Cara terbaik adalah ....","opts":[{"t":"Mengomunikasikan kapasitas Anda dan menegosiasikan prioritas bersama","s":5},{"t":"Meminta kejelasan urgensi tiap tugas lalu menyusun prioritas","s":4},{"t":"Menerima semuanya dan bekerja hingga kelelahan","s":3},{"t":"Menolak semuanya tanpa penjelasan","s":2},{"t":"Mengerjakan asal-asalan semuanya","s":1}],"ex":"Komunikasi kapasitas dan negosiasi prioritas mencegah kelelahan."},
{"id":"TKP-4698","q":"Seorang rekan satu tim tidak pernah mau didelegasikan tugas tambahan dengan alasan sibuk. Sikap terbaik Anda adalah ....","opts":[{"t":"Meninjau beban kerjanya secara objektif sebelum menilai alasannya","s":5},{"t":"Mendiskusikan pembagian beban yang adil dalam tim","s":4},{"t":"Memaksanya menerima tugas tambahan","s":3},{"t":"Membiarkannya dan membebani anggota lain","s":2},{"t":"Menyebarkan bahwa ia tidak solid","s":1}],"ex":"Tinjauan objektif beban kerja memastikan keadilan sebelum menilai."},
{"id":"TKP-4699","q":"Delegasi tugas dalam tim Anda tidak pernah dievaluasi hasilnya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan evaluasi rutin hasil delegasi sebagai pembelajaran tim","s":5},{"t":"Berinisiatif mengevaluasi delegasi yang Anda berikan","s":4},{"t":"Membiarkannya karena evaluasi membuang waktu","s":3},{"t":"Berhenti mendelegasikan","s":2},{"t":"Menyalahkan hasil buruk tanpa evaluasi","s":1}],"ex":"Evaluasi rutin mengubah delegasi menjadi proses pembelajaran tim."},
{"id":"TKP-4700","q":"Seorang anggota tim baru bingung dengan sistem pembagian tugas yang berlaku. Cara terbaik adalah ....","opts":[{"t":"Menjelaskan sistem pembagian tugas dan mendampinginya di awal","s":5},{"t":"Memberinya panduan tertulis tentang alur tugas tim","s":4},{"t":"Membiarkannya belajar sendiri","s":3},{"t":"Menertawakannya karena tidak paham","s":2},{"t":"Tidak memberinya tugas sama sekali","s":1}],"ex":"Penjelasan dan pendampingan awal mempercepat adaptasi anggota baru."}
,
{"id":"TKP-4701","q":"Anda ditunjuk memimpin sebuah tim yang anggotanya lebih senior dari Anda. Sikap terbaik Anda adalah ....","opts":[{"t":"Memimpin dengan rendah hati, menghargai pengalaman mereka, dan mengajak berkolaborasi","s":5},{"t":"Membangun kepercayaan lewat kompetensi dan konsistensi kerja","s":4},{"t":"Bersikap otoriter agar mereka patuh","s":3},{"t":"Menyerahkan semua keputusan kepada yang paling senior","s":2},{"t":"Menolak penunjukan tersebut","s":1}],"ex":"Kepemimpinan rendah hati yang menghargai pengalaman memenangkan respek senior."},
{"id":"TKP-4702","q":"Sebagai koordinator tim, dua anggota Anda berselisih paham dan meminta Anda memihak. Tindakan paling tepat adalah ....","opts":[{"t":"Bersikap netral, mendengarkan keduanya, dan memfasilitasi penyelesaian adil","s":5},{"t":"Mengajak keduanya berdialog mencari solusi yang disepakati","s":4},{"t":"Memihak yang menurut Anda benar","s":3},{"t":"Membiarkan mereka menyelesaikan sendiri","s":2},{"t":"Menghukum keduanya agar jera","s":1}],"ex":"Netralitas dan fasilitasi adil adalah kunci memimpin penyelesaian konflik."},
{"id":"TKP-4703","q":"Tim yang Anda pimpin gagal mencapai target yang ditetapkan. Sikap terbaik Anda sebagai pemimpin adalah ....","opts":[{"t":"Bertanggung jawab, mengevaluasi bersama tim, dan menyusun perbaikan","s":5},{"t":"Menganalisis penyebab kegagalan secara objektif bersama anggota","s":4},{"t":"Menyalahkan anggota yang kinerjanya buruk","s":3},{"t":"Menyembunyikan kegagalan dari pihak luar","s":2},{"t":"Mengundurkan diri sebagai pemimpin","s":1}],"ex":"Tanggung jawab dan evaluasi bersama membangun kepercayaan dan perbaikan."},
{"id":"TKP-4704","q":"Seorang anggota tim yang Anda pimpin berprestasi jauh di atas yang lain. Tindakan paling tepat adalah ....","opts":[{"t":"Memberinya apresiasi sekaligus mendorongnya membantu mengembangkan rekan lain","s":5},{"t":"Mengakui prestasinya secara terbuka di depan tim","s":4},{"t":"Membiarkannya tanpa apresiasi agar tidak sombong","s":3},{"t":"Menambah bebannya karena ia mampu","s":2},{"t":"Mengabaikannya agar yang lain tidak iri","s":1}],"ex":"Apresiasi yang disertai dorongan berbagi memperkuat tim secara keseluruhan."},
{"id":"TKP-4705","q":"Sebagai pemimpin tim, Anda harus menyampaikan keputusan sulit yang tidak populer. Cara terbaik adalah ....","opts":[{"t":"Menjelaskan alasan keputusan dengan jujur dan membuka ruang dialog","s":5},{"t":"Menyampaikan dengan empati sambil menegaskan keharusannya","s":4},{"t":"Menyampaikan tanpa penjelasan apa pun","s":3},{"t":"Menunda penyampaian selama mungkin","s":2},{"t":"Melempar tanggung jawab keputusan kepada pihak lain","s":1}],"ex":"Kejujuran alasan dan ruang dialog membuat keputusan sulit bisa diterima."},
{"id":"TKP-4706","q":"Anggota tim yang Anda pimpin terlihat kehilangan motivasi kerja. Tindakan paling tepat adalah ....","opts":[{"t":"Berbicara personal untuk memahami penyebabnya dan mencari solusi bersama","s":5},{"t":"Memberinya tantangan baru yang sesuai minatnya","s":4},{"t":"Mengancam dengan sanksi agar termotivasi","s":3},{"t":"Membiarkannya karena motivasi urusan pribadi","s":2},{"t":"Menggantinya dengan orang lain","s":1}],"ex":"Memahami penyebab dan solusi personal mengembalikan motivasi secara berkelanjutan."},
{"id":"TKP-4707","q":"Sebagai koordinator, Anda melihat seorang anggota tim diperlakukan tidak adil oleh anggota lain. Sikap terbaik Anda adalah ....","opts":[{"t":"Menegakkan keadilan dengan menengahi dan memastikan perlakuan setara","s":5},{"t":"Berbicara dengan pihak yang tidak adil secara pribadi","s":4},{"t":"Membiarkannya karena bukan urusan Anda","s":3},{"t":"Memihak korban secara terbuka dan menghukum pelaku","s":2},{"t":"Mengabaikan karena takut ikut bermasalah","s":1}],"ex":"Penegakan keadilan yang tegas namun bijak melindungi anggota yang dirugikan."},
{"id":"TKP-4708","q":"Tim yang Anda pimpin terpecah menjadi kelompok-kelompok kecil yang eksklusif. Cara terbaik adalah ....","opts":[{"t":"Menciptakan kegiatan dan tugas yang memaksa kolaborasi lintas kelompok","s":5},{"t":"Melakukan rotasi penugasan agar anggota saling mengenal","s":4},{"t":"Membiarkannya karena itu dinamika alami","s":3},{"t":"Membubarkan kelompok-kelompok itu secara paksa","s":2},{"t":"Memihak kelompok terbesar","s":1}],"ex":"Tugas kolaboratif lintas kelompok melebur sekat secara alami."},
{"id":"TKP-4709","q":"Sebagai pemimpin tim, Anda melakukan kesalahan dalam pengambilan keputusan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengakui kesalahan secara terbuka dan mengajak tim memperbaikinya","s":5},{"t":"Bertanggung jawab penuh tanpa melempar kesalahan","s":4},{"t":"Menyembunyikan kesalahan agar wibawa terjaga","s":3},{"t":"Menyalahkan anggota yang memberi masukan","s":2},{"t":"Menyalahkan keadaan","s":1}],"ex":"Pengakuan terbuka justru memperkuat wibawa dan kepercayaan tim."},
{"id":"TKP-4710","q":"Seorang anggota tim yang Anda pimpin lebih pintar dan sering mengkritik keputusan Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Menerima kritiknya sebagai masukan berharga dan melibatkannya dalam perumusan keputusan","s":5},{"t":"Mendiskusikan kritiknya secara terbuka dengan tim","s":4},{"t":"Menekannya agar tidak mengkritik","s":3},{"t":"Menyingkirkannya dari tim","s":2},{"t":"Mengikuti semua maunya agar tidak dikritik","s":1}],"ex":"Melibatkan pengkritik cerdas dalam perumusan mengubah kritik menjadi kontribusi."},
{"id":"TKP-4711","q":"Sebagai koordinator tim, Anda harus membagi bonus kinerja yang terbatas. Cara terbaik adalah ....","opts":[{"t":"Membaginya berdasarkan kriteria kontribusi yang transparan dan disepakati","s":5},{"t":"Mendiskusikan pembagiannya secara terbuka dengan tim","s":4},{"t":"Membagi rata agar tidak ada yang protes","s":3},{"t":"Memberikan semuanya kepada yang paling dekat dengan Anda","s":2},{"t":"Menyimpannya untuk diri sendiri","s":1}],"ex":"Kriteria transparan yang disepakati membuat pembagian terbatas bisa diterima."},
{"id":"TKP-4712","q":"Tim yang Anda pimpin harus bekerja dengan tim lain yang pemimpinnya sulit diajak kerja sama. Sikap terbaik Anda adalah ....","opts":[{"t":"Membangun komunikasi profesional dan fokus pada kepentingan bersama kedua tim","s":5},{"t":"Mengajaknya berdialog untuk menyelaraskan cara kerja","s":4},{"t":"Bersaing dengannya menunjukkan siapa lebih baik","s":3},{"t":"Menghindari kerja sama dengannya","s":2},{"t":"Menjelek-jelekkannya di depan tim Anda","s":1}],"ex":"Komunikasi profesional yang fokus pada kepentingan bersama melampaui ego pribadi."},
{"id":"TKP-4713","q":"Sebagai pemimpin, Anda mengetahui ada anggota tim yang melanggar aturan ringan. Tindakan paling tepat adalah ....","opts":[{"t":"Menegurnya secara pribadi dan mengingatkannya pada aturan yang berlaku","s":5},{"t":"Memberinya peringatan lisan dengan tenggat perbaikan","s":4},{"t":"Membiarkannya karena pelanggarannya ringan","s":3},{"t":"Menghukumnya berat di depan tim sebagai contoh","s":2},{"t":"Melaporkannya langsung tanpa teguran","s":1}],"ex":"Teguran pribadi yang proporsional menegakkan aturan tanpa merusak hubungan."},
{"id":"TKP-4714","q":"Anggota tim yang Anda pimpin meminta Anda merahasiakan kesalahannya dari tim. Sikap terbaik Anda adalah ....","opts":[{"t":"Menjaga kepercayaan sambil membantunya memperbaiki kesalahan tersebut","s":5},{"t":"Menyarankan ia mengakuinya sendiri dengan pendampingan Anda","s":4},{"t":"Langsung membocorkannya ke tim","s":3},{"t":"Menutupinya sepenuhnya tanpa perbaikan","s":2},{"t":"Menggunakannya untuk menekannya","s":1}],"ex":"Menjaga kepercayaan sambil mendorong perbaikan menyeimbangkan etika dan empati."},
{"id":"TKP-4715","q":"Sebagai koordinator tim, Anda diminta pimpinan melaporkan kinerja anggota yang buruk. Tindakan paling tepat adalah ....","opts":[{"t":"Melaporkan secara objektif disertai upaya pembinaan yang sudah dilakukan","s":5},{"t":"Menyampaikan fakta apa adanya tanpa melebih-lebihkan","s":4},{"t":"Menutupi keburukannya demi menjaga nama tim","s":3},{"t":"Melebih-lebihkan keburukannya","s":2},{"t":"Menolak melaporkan","s":1}],"ex":"Laporan objektif disertai upaya pembinaan menunjukkan kepemimpinan bertanggung jawab."},
{"id":"TKP-4716","q":"Tim yang Anda pimpin berhasil besar, tetapi ada anggota yang iri pada anggota lain. Cara terbaik adalah ....","opts":[{"t":"Menekankan bahwa keberhasilan adalah hasil kerja seluruh tim","s":5},{"t":"Memberi apresiasi merata sesuai kontribusi masing-masing","s":4},{"t":"Membiarkan kecemburuan itu","s":3},{"t":"Memihak yang berprestasi lebih","s":2},{"t":"Menyembunyikan keberhasilan tim","s":1}],"ex":"Penekanan pada kerja kolektif dan apresiasi merata meredakan kecemburuan."},
{"id":"TKP-4717","q":"Sebagai pemimpin tim, Anda menghadapi anggota yang selalu menentang setiap kebijakan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengajaknya berdialog memahami keberatannya dan melibatkannya dalam perumusan","s":5},{"t":"Mendengarkan kritiknya sebagai bahan evaluasi kebijakan","s":4},{"t":"Mengabaikan penentangannya","s":3},{"t":"Mengeluarkannya dari tim","s":2},{"t":"Melawannya dengan otoritas penuh","s":1}],"ex":"Dialog dan pelibatan mengubah penentang menjadi bagian solusi."},
{"id":"TKP-4718","q":"Anda memimpin tim dengan anggota dari latar belakang yang sangat beragam. Tindakan paling tepat adalah ....","opts":[{"t":"Membangun nilai kebersamaan tim yang menghargai keberagaman","s":5},{"t":"Mempelajari dan menghormati perbedaan tiap anggota","s":4},{"t":"Memaksa semua mengikuti satu pola","s":3},{"t":"Membiarkan mereka berkelompok sesuai latar belakang","s":2},{"t":"Mengabaikan perbedaan itu","s":1}],"ex":"Nilai kebersamaan yang menghargai keberagaman menyatukan tim heterogen."},
{"id":"TKP-4719","q":"Sebagai koordinator, Anda harus memilih anggota tim untuk tugas ke luar kota yang diinginkan banyak orang. Cara terbaik adalah ....","opts":[{"t":"Menentukan berdasarkan kriteria objektif seperti kompetensi dan rotasi","s":5},{"t":"Membahasnya terbuka dengan tim agar tidak ada prasangka","s":4},{"t":"Memilih yang paling dekat dengan Anda","s":3},{"t":"Menunjuk diri sendiri","s":2},{"t":"Mengundi tanpa kriteria","s":1}],"ex":"Kriteria objektif dan keterbukaan mencegah prasangka dalam penunjukan."},
{"id":"TKP-4720","q":"Tim yang Anda pimpin dituntut hasil cepat tetapi kualitas tidak boleh turun. Sikap terbaik Anda adalah ....","opts":[{"t":"Menyusun strategi kerja efisien bersama tim tanpa mengorbankan standar kualitas","s":5},{"t":"Membagi tugas secara optimal sesuai kekuatan masing-masing anggota","s":4},{"t":"Memaksa lembur terus-menerus","s":3},{"t":"Mengorbankan kualitas demi kecepatan","s":2},{"t":"Menolak tuntutan tersebut","s":1}],"ex":"Strategi efisien berbasis kekuatan anggota menyeimbangkan kecepatan dan kualitas."},
{"id":"TKP-4721","q":"Seorang anggota tim yang Anda pimpin menyampaikan ide yang berisiko tinggi. Tindakan paling tepat adalah ....","opts":[{"t":"Mengkaji risiko bersama tim dan mengujinya dalam skala kecil","s":5},{"t":"Mengapresiasi keberaniannya sambil menilai kelayakannya objektif","s":4},{"t":"Menolak langsung karena berisiko","s":3},{"t":"Menerima tanpa kajian","s":2},{"t":"Menertawakan idenya","s":1}],"ex":"Kajian risiko dan uji skala kecil mengelola ide berisiko secara bijak."},
{"id":"TKP-4722","q":"Sebagai pemimpin tim, Anda dikritik anggota karena jarang hadir mendampingi. Sikap terbaik Anda adalah ....","opts":[{"t":"Menerima kritik, memperbaiki kehadiran, dan menyepakati pola pendampingan","s":5},{"t":"Menjelaskan kendala Anda dan mencari solusi pendampingan alternatif","s":4},{"t":"Membela diri bahwa Anda sibuk","s":3},{"t":"Mengabaikan kritik tersebut","s":2},{"t":"Balik mengkritik anggota yang mengeluh","s":1}],"ex":"Penerimaan kritik dan perbaikan nyata membangun kepercayaan anggota."},
{"id":"TKP-4723","q":"Dua anggota tim yang Anda pimpin bersaing tidak sehat memperebutkan perhatian Anda. Cara terbaik adalah ....","opts":[{"t":"Memberi perhatian dan apresiasi proporsional berdasarkan kontribusi objektif","s":5},{"t":"Menegaskan bahwa penilaian Anda berbasis kinerja, bukan kedekatan","s":4},{"t":"Memihak salah satu yang lebih unggul","s":3},{"t":"Membiarkan persaingan berlanjut","s":2},{"t":"Mengadu domba keduanya","s":1}],"ex":"Perhatian proporsional berbasis kinerja objektif meredakan persaingan tidak sehat."},
{"id":"TKP-4724","q":"Sebagai koordinator tim, Anda harus menegur anggota senior yang melanggar kesepakatan. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur dengan hormat secara pribadi sambil menegaskan kesepakatan berlaku untuk semua","s":5},{"t":"Mengingatkannya dengan bahasa yang menjaga martabatnya","s":4},{"t":"Membiarkannya karena ia senior","s":3},{"t":"Menegurnya keras di depan tim","s":2},{"t":"Melaporkannya tanpa teguran dulu","s":1}],"ex":"Teguran hormat yang menegaskan kesetaraan aturan menjaga wibawa semua pihak."},
{"id":"TKP-4725","q":"Tim yang Anda pimpin akan dibubarkan setelah proyek selesai dan anggota cemas soal penugasan berikutnya. Sikap terbaik Anda adalah ....","opts":[{"t":"Memberi kepastian informasi dan membantu menyiapkan transisi tiap anggota","s":5},{"t":"Mengapresiasi kontribusi mereka selama dalam tim Anda","s":4},{"t":"Membiarkan mereka cemas karena bukan urusan Anda","s":3},{"t":"Menyembunyikan informasi pembubaran","s":2},{"t":"Menyalahkan keadaan","s":1}],"ex":"Kepastian informasi dan bantuan transisi menunjukkan kepemimpinan yang bertanggung jawab sampai akhir."}
,
{"id":"TKP-4726","q":"Tim Anda kedatangan anggota baru yang langsung diberi tugas berat. Sikap terbaik Anda sebagai rekan adalah ....","opts":[{"t":"Menawarkan bantuan dan membimbingnya melewati masa adaptasi awal","s":5},{"t":"Berbagi pengalaman dan tips mengerjakan tugas di tim ini","s":4},{"t":"Membiarkannya berjuang sendiri agar cepat mandiri","s":3},{"t":"Menertawakannya saat ia kesulitan","s":2},{"t":"Mengambil alih tugasnya agar cepat selesai","s":1}],"ex":"Bimbingan di masa adaptasi mempercepat kontribusi anggota baru."},
{"id":"TKP-4727","q":"Seorang anggota baru tim Anda malu bertanya meski jelas kebingungan. Cara terbaik adalah ....","opts":[{"t":"Proaktif menawarkan bantuan dan menciptakan suasana aman untuk bertanya","s":5},{"t":"Menanyakan langsung kesulitan yang ia hadapi dengan ramah","s":4},{"t":"Membiarkannya karena bertanya adalah inisiatif pribadi","s":3},{"t":"Menegurnya karena tidak proaktif","s":2},{"t":"Menggosipkan kebingungannya","s":1}],"ex":"Suasana aman dan tawaran proaktif membuka keberanian anggota baru bertanya."},
{"id":"TKP-4728","q":"Anggota baru tim Anda membawa cara kerja dari tempat lama yang berbeda dengan tim ini. Sikap terbaik Anda adalah ....","opts":[{"t":"Menghargai pengalamannya sambil mengenalkannya pada cara kerja tim ini","s":5},{"t":"Mendengarkan idenya, siapa tahu ada yang bisa diadopsi tim","s":4},{"t":"Memaksanya langsung mengikuti cara tim ini","s":3},{"t":"Mengejek cara kerjanya yang berbeda","s":2},{"t":"Mengucilkannya karena berbeda","s":1}],"ex":"Menghargai pengalaman lama sambil mengenalkan cara baru menyeimbangkan adaptasi."},
{"id":"TKP-4729","q":"Tim Anda tidak memiliki program orientasi untuk anggota baru. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan penyusunan program orientasi sederhana untuk anggota baru","s":5},{"t":"Berinisiatif mendampingi anggota baru secara informal","s":4},{"t":"Membiarkannya karena orientasi bukan urusan Anda","s":3},{"t":"Menuntut dibentuknya program resmi yang rumit","s":2},{"t":"Mengabaikan anggota baru","s":1}],"ex":"Usulan orientasi sederhana dan pendampingan informal mempercepat integrasi."},
{"id":"TKP-4730","q":"Seorang anggota baru membuat kesalahan fatal karena tidak diberi pengarahan. Sikap terbaik tim Anda adalah ....","opts":[{"t":"Bertanggung jawab bersama, memperbaikinya, dan memperbaiki sistem pengarahan","s":5},{"t":"Membimbingnya memperbaiki kesalahan tanpa menyalahkannya","s":4},{"t":"Menyalahkannya sepenuhnya","s":3},{"t":"Menuntutnya mengganti kerugian","s":2},{"t":"Mengeluarkannya dari tim","s":1}],"ex":"Tanggung jawab bersama dan perbaikan sistem mencegah kesalahan berulang."},
{"id":"TKP-4731","q":"Anggota baru tim Anda sangat berbakat tetapi arogan terhadap rekan senior. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menasihatinya dengan bijak tentang pentingnya menghormati semua rekan","s":5},{"t":"Memberinya contoh bagaimana tim ini saling menghargai","s":4},{"t":"Membiarkannya karena bakatnya dibutuhkan","s":3},{"t":"Mengucilkannya sebagai pelajaran","s":2},{"t":"Melawannya dengan kesombongan juga","s":1}],"ex":"Nasihat bijak tentang sikap menyeimbangkan bakat dan kerendahan hati."},
{"id":"TKP-4732","q":"Seorang anggota baru enggan mengikuti kegiatan kebersamaan tim. Tindakan paling tepat adalah ....","opts":[{"t":"Mengajaknya dengan ramah dan menjelaskan manfaat kebersamaan tim","s":5},{"t":"Memberinya waktu beradaptasi sambil terus mengajak","s":4},{"t":"Memaksanya ikut semua kegiatan","s":3},{"t":"Membiarkannya terisolasi","s":2},{"t":"Menggosipkan keengganannya","s":1}],"ex":"Ajakan ramah dan penjelasan manfaat mengintegrasikan anggota baru secara alami."},
{"id":"TKP-4733","q":"Tim Anda menerima anggota pindahan dari unit lain yang membawa kebiasaan kurang baik. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengenalkan nilai dan kebiasaan positif tim ini dengan keteladanan","s":5},{"t":"Berbicara dengannya tentang harapan tim ini","s":4},{"t":"Langsung menegur kebiasaan buruknya","s":3},{"t":"Menolak kehadirannya","s":2},{"t":"Mengikuti kebiasaan buruknya","s":1}],"ex":"Keteladanan dan komunikasi harapan mengubah kebiasaan secara positif."},
{"id":"TKP-4734","q":"Seorang anggota baru tim Anda terlalu sering bergantung pada Anda untuk setiap hal kecil. Cara terbaik adalah ....","opts":[{"t":"Melatih kemandiriannya bertahap sambil tetap tersedia untuk hal penting","s":5},{"t":"Memberinya panduan tertulis agar bisa belajar mandiri","s":4},{"t":"Terus membantunya untuk semua hal","s":3},{"t":"Memarahinya agar mandiri","s":2},{"t":"Mengabaikannya sama sekali","s":1}],"ex":"Pelatihan kemandirian bertahap mengubah ketergantungan menjadi kepercayaan diri."},
{"id":"TKP-4735","q":"Anggota baru tim Anda dikucilkan oleh sekelompok anggota lama. Tindakan paling tepat adalah ....","opts":[{"t":"Menegur kelompok itu dan aktif merangkul anggota baru ke dalam tim","s":5},{"t":"Mengajak anggota baru berinteraksi lebih luas dengan seluruh tim","s":4},{"t":"Membiarkannya karena itu dinamika alami","s":3},{"t":"Ikut mengucilkannya agar diterima kelompok lama","s":2},{"t":"Melaporkan sebagai konflik tanpa solusi","s":1}],"ex":"Teguran dan perangkulan aktif menghentikan pengucilan dan membangun inklusivitas."},
{"id":"TKP-4736","q":"Seorang anggota baru mempertanyakan cara kerja tim yang sudah lama berjalan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendengarkan dengan terbuka, siapa tahu ada perbaikan yang bisa diadopsi","s":5},{"t":"Menjelaskan alasan di balik cara kerja yang berlaku","s":4},{"t":"Menyuruhnya diam dan mengikuti saja","s":3},{"t":"Menertawakan pertanyaannya","s":2},{"t":"Menganggapnya tidak sopan","s":1}],"ex":"Keterbukaan pada pertanyaan baru bisa membawa perbaikan bagi tim."},
{"id":"TKP-4737","q":"Tim Anda kedatangan anggota baru di tengah proyek yang sedang kritis. Cara terbaik adalah ....","opts":[{"t":"Memberinya tugas yang sesuai kapasitas sambil mengenalkannya pada tim secara bertahap","s":5},{"t":"Menugaskan seorang pendamping khusus untuknya","s":4},{"t":"Langsung memberinya tugas kritis","s":3},{"t":"Mengabaikannya sampai proyek selesai","s":2},{"t":"Menolak menerima anggota baru saat kritis","s":1}],"ex":"Penugasan bertahap dengan pendamping mengintegrasikan tanpa mengganggu proyek kritis."},
{"id":"TKP-4738","q":"Seorang anggota baru tim Anda minder karena merasa kemampuannya di bawah rekan lain. Tindakan paling tepat adalah ....","opts":[{"t":"Meyakinkannya bahwa setiap orang punya kelebihan dan memberinya kesempatan","s":5},{"t":"Menugaskannya pekerjaan yang bisa membangun kepercayaan dirinya","s":4},{"t":"Membiarkannya minder karena itu perasaannya","s":3},{"t":"Setuju bahwa ia memang kurang mampu","s":2},{"t":"Mengejek kemampuannya","s":1}],"ex":"Keyakinan dan kesempatan membangun kepercayaan diri anggota baru."},
{"id":"TKP-4739","q":"Anggota baru tim Anda langsung mengkritik cara kerja tim di minggu pertamanya. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendengarkan kritiknya dengan bijak dan menjelaskan konteks tim ini","s":5},{"t":"Mengapresiasi keberaniannya sambil memintanya memahami dulu","s":4},{"t":"Menegurnya karena belum pantas mengkritik","s":3},{"t":"Mengucilkannya karena tidak sopan","s":2},{"t":"Mengikuti semua kritiknya","s":1}],"ex":"Mendengarkan bijak sambil memberi konteks menyeimbangkan kritik dan adaptasi."},
{"id":"TKP-4740","q":"Seorang anggota baru tidak memahami istilah dan singkatan yang dipakai tim Anda. Cara terbaik adalah ....","opts":[{"t":"Menyusun daftar istilah tim dan menjelaskannya dengan sabar","s":5},{"t":"Menjelaskan setiap kali ia bertanya tanpa bosan","s":4},{"t":"Membiarkannya menebak-nebak sendiri","s":3},{"t":"Menertawakannya setiap ia salah paham","s":2},{"t":"Melarang pemakaian istilah itu","s":1}],"ex":"Daftar istilah dan kesabaran mempercepat pemahaman anggota baru."},
{"id":"TKP-4741","q":"Tim Anda memiliki tradisi penyambutan anggota baru yang dirasa memberatkan. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan tradisi penyambutan yang ramah dan tidak memberatkan","s":5},{"t":"Mendiskusikan ulang tradisi itu dalam forum tim","s":4},{"t":"Memaksa anggota baru mengikuti tradisi lama","s":3},{"t":"Membiarkan tradisi memberatkan itu","s":2},{"t":"Menghapus semua tradisi tim","s":1}],"ex":"Tradisi penyambutan yang ramah membuat anggota baru merasa diterima."},
{"id":"TKP-4742","q":"Seorang anggota baru tim Anda berasal dari daerah yang jauh dan kesulitan beradaptasi. Sikap terbaik Anda adalah ....","opts":[{"t":"Membantunya beradaptasi dengan lingkungan kerja dan sekitarnya","s":5},{"t":"Mengajaknya berinteraksi agar tidak merasa sendiri","s":4},{"t":"Membiarkannya beradaptasi sendiri","s":3},{"t":"Mengejek logatnya","s":2},{"t":"Mengucilkannya karena berbeda","s":1}],"ex":"Bantuan adaptasi dan kehangatan interaksi mempercepat integrasi anggota baru."},
{"id":"TKP-4743","q":"Anggota baru tim Anda diberi tugas tanpa penjelasan target yang jelas. Tindakan paling tepat Anda sebagai rekan adalah ....","opts":[{"t":"Membantunya memahami target dan cara mencapainya","s":5},{"t":"Menyarankannya meminta kejelasan target kepada koordinator","s":4},{"t":"Membiarkannya bekerja tanpa target jelas","s":3},{"t":"Menyalahkannya bila hasilnya tidak sesuai","s":2},{"t":"Mengambil alih tugasnya","s":1}],"ex":"Membantu memahami target mencegah kegagalan akibat ketidakjelasan."},
{"id":"TKP-4744","q":"Seorang anggota baru tim Anda sangat pendiam dan tidak pernah ikut diskusi. Cara terbaik adalah ....","opts":[{"t":"Memberinya kesempatan bicara dalam suasana yang aman dan mendukung","s":5},{"t":"Menanyakan pendapatnya secara personal terlebih dahulu","s":4},{"t":"Membiarkannya diam selamanya","s":3},{"t":"Memaksanya bicara di depan semua orang","s":2},{"t":"Menganggapnya tidak kompeten","s":1}],"ex":"Suasana aman dan pendekatan personal membuka partisipasi anggota pendiam."},
{"id":"TKP-4745","q":"Tim Anda sering berganti anggota sehingga kekompakan sulit terbangun. Tindakan paling tepat adalah ....","opts":[{"t":"Membangun sistem kerja dan dokumentasi yang memudahkan anggota baru beradaptasi","s":5},{"t":"Mengadakan kegiatan pengakraban setiap ada anggota baru","s":4},{"t":"Menyerah membangun kekompakan","s":3},{"t":"Menyalahkan pergantian anggota","s":2},{"t":"Menolak menerima anggota baru","s":1}],"ex":"Sistem dan dokumentasi yang baik menjaga kontinuitas meski anggota berganti."},
{"id":"TKP-4746","q":"Seorang anggota baru tim Anda mengeluh tentang beban kerja di minggu pertama. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendengarkan keluhannya dan membantunya mengatur prioritas kerja","s":5},{"t":"Menjelaskan bahwa masa adaptasi memang menantang dan menawarkannya bantuan","s":4},{"t":"Menyuruhnya berhenti mengeluh","s":3},{"t":"Mengabaikan keluhannya","s":2},{"t":"Menyebarkan keluhannya sebagai bahan gosip","s":1}],"ex":"Empati dan bantuan prioritas membantu anggota baru melewati masa adaptasi."},
{"id":"TKP-4747","q":"Anggota baru tim Anda tidak sengaja merusak peralatan kerja tim. Tindakan paling tepat adalah ....","opts":[{"t":"Membantunya melaporkan dan memperbaiki dengan fokus pada pencegahan","s":5},{"t":"Menenangkannya dan menjelaskan prosedur penggunaan yang benar","s":4},{"t":"Memarahinya habis-habisan","s":3},{"t":"Menuntutnya mengganti sendiri","s":2},{"t":"Menyembunyikan kerusakan itu","s":1}],"ex":"Fokus pada perbaikan dan pencegahan lebih konstruktif daripada menyalahkan."},
{"id":"TKP-4748","q":"Seorang anggota baru ingin langsung memimpin proyek meski belum paham tim. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mengapresiasi semangatnya sambil menjelaskan tahapan berkontribusi dalam tim","s":5},{"t":"Memberinya peran bertahap sesuai pemahamannya tentang tim","s":4},{"t":"Langsung memberinya pimpinan proyek","s":3},{"t":"Menolak mentah-mentah keinginannya","s":2},{"t":"Menertawakan ambisinya","s":1}],"ex":"Apresiasi dan peran bertahap menyalurkan ambisi secara sehat."},
{"id":"TKP-4749","q":"Tim Anda memiliki anggota baru yang usianya jauh lebih muda dari anggota lain. Sikap terbaik Anda adalah ....","opts":[{"t":"Menghargai perspektif segarnya dan menjembatani perbedaan generasi","s":5},{"t":"Melibatkannya setara tanpa memandang usia","s":4},{"t":"Meremehkannya karena masih muda","s":3},{"t":"Memaksanya mengikuti semua kemauan senior","s":2},{"t":"Mengucilkannya dari pergaulan","s":1}],"ex":"Menghargai perspektif segar dan kesetaraan menjembatani perbedaan generasi."},
{"id":"TKP-4750","q":"Seorang anggota baru tim Anda meminta umpan balik atas kinerjanya di bulan pertama. Tindakan paling tepat adalah ....","opts":[{"t":"Memberi umpan balik jujur, seimbang, dan membangun","s":5},{"t":"Mengapresiasi kemajuannya dan menunjukkan area perbaikan","s":4},{"t":"Menolak memberi umpan balik","s":3},{"t":"Hanya menyampaikan kekurangannya","s":2},{"t":"Membohonginya dengan pujian palsu","s":1}],"ex":"Umpan balik jujur dan seimbang mempercepat perkembangan anggota baru."}
,
{"id":"TKP-4751","q":"Tim Anda tidak pernah melakukan evaluasi kinerja bersama. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan evaluasi rutin yang konstruktif dan disepakati tim","s":5},{"t":"Berinisiatif melakukan refleksi informal bersama rekan","s":4},{"t":"Membiarkannya karena evaluasi menakutkan","s":3},{"t":"Menuntut evaluasi formal yang kaku","s":2},{"t":"Mengevaluasi orang lain diam-diam","s":1}],"ex":"Evaluasi rutin yang konstruktif menjadi motor perbaikan tim."},
{"id":"TKP-4752","q":"Seorang rekan satu tim tersinggung dengan umpan balik yang Anda sampaikan. Sikap terbaik Anda adalah ....","opts":[{"t":"Meminta maaf atas cara penyampaian dan mengulanginya dengan lebih baik","s":5},{"t":"Menjelaskan niat baik Anda dan fokus pada perbaikan","s":4},{"t":"Berhenti memberi umpan balik kepadanya selamanya","s":3},{"t":"Menyalahkannya karena terlalu sensitif","s":2},{"t":"Menyebarkan bahwa ia anti kritik","s":1}],"ex":"Permintaan maaf dan perbaikan cara menjaga umpan balik tetap berjalan."},
{"id":"TKP-4753","q":"Dalam evaluasi tim, seorang anggota hanya memuji diri sendiri. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Mengarahkan evaluasi pada fakta kontribusi dan area perbaikan setiap anggota","s":5},{"t":"Mengingatkannya bahwa evaluasi bertujuan perbaikan bersama","s":4},{"t":"Membiarkannya memuji diri","s":3},{"t":"Menjatuhkannya dengan kritik pedas","s":2},{"t":"Membatalkan evaluasi","s":1}],"ex":"Evaluasi berbasis fakta menjaga objektivitas dan tujuan perbaikan."},
{"id":"TKP-4754","q":"Tim Anda enggan memberi umpan balik karena takut menyinggung. Tindakan paling tepat adalah ....","opts":[{"t":"Membangun budaya umpan balik yang aman dengan memberi contoh terlebih dahulu","s":5},{"t":"Mengajarkan teknik umpan balik yang membangun kepada tim","s":4},{"t":"Membiarkan budaya diam itu","s":3},{"t":"Memaksa semua memberi umpan balik","s":2},{"t":"Memberi umpan balik kasar agar terbiasa","s":1}],"ex":"Contoh dan teknik yang tepat membangun budaya umpan balik yang aman."},
{"id":"TKP-4755","q":"Seorang rekan satu tim menolak umpan balik dengan alasan sudah berpengalaman. Sikap terbaik Anda adalah ....","opts":[{"t":"Menghormati pengalamannya sambil menjelaskan umpan balik untuk perbaikan bersama","s":5},{"t":"Menyampaikan umpan balik berbasis data yang sulit dibantah","s":4},{"t":"Berhenti memberinya umpan balik","s":3},{"t":"Menertawakan keengganannya","s":2},{"t":"Melaporkannya sebagai antikritik","s":1}],"ex":"Umpan balik berbasis data dan tujuan bersama sulit ditolak siapa pun."},
{"id":"TKP-4756","q":"Hasil evaluasi tim menunjukkan kinerja Anda yang paling rendah. Tindakan paling tepat adalah ....","opts":[{"t":"Menerima dengan lapang dan menyusun rencana perbaikan diri","s":5},{"t":"Meminta masukan rekan tentang cara meningkatkan kinerja","s":4},{"t":"Menolak hasil evaluasi","s":3},{"t":"Menyalahkan metode evaluasinya","s":2},{"t":"Menyabotase evaluasi berikutnya","s":1}],"ex":"Penerimaan lapang dan rencana perbaikan mengubah evaluasi menjadi kemajuan."},
{"id":"TKP-4757","q":"Seorang anggota tim memanipulasi hasil evaluasi demi terlihat baik. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan sistem evaluasi berbasis bukti yang transparan","s":5},{"t":"Menyampaikan keberatan dengan data yang objektif","s":4},{"t":"Membiarkannya karena bukan urusan Anda","s":3},{"t":"Ikut memanipulasi agar seimbang","s":2},{"t":"Menyebarkan kecurangannya","s":1}],"ex":"Sistem evaluasi berbasis bukti mencegah manipulasi secara struktural."},
{"id":"TKP-4758","q":"Tim Anda melakukan evaluasi tetapi tidak ada tindak lanjut perbaikannya. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan rencana tindak lanjut konkret dengan penanggung jawab","s":5},{"t":"Berinisiatif menjalankan perbaikan dari sisi Anda","s":4},{"t":"Membiarkannya karena sudah biasa","s":3},{"t":"Menolak ikut evaluasi berikutnya","s":2},{"t":"Mengkritik tim yang tidak serius","s":1}],"ex":"Rencana tindak lanjut konkret memastikan evaluasi berdampak nyata."},
{"id":"TKP-4759","q":"Seorang rekan satu tim meminta Anda memberi penilaian baik untuknya dalam evaluasi. Tindakan paling tepat adalah ....","opts":[{"t":"Menolak dengan sopan dan menilai secara objektif sesuai fakta","s":5},{"t":"Menjelaskan bahwa penilaian objektif justru membantunya berkembang","s":4},{"t":"Memberinya penilaian baik demi menjaga hubungan","s":3},{"t":"Memberi penilaian buruk sebagai hukuman","s":2},{"t":"Memerasnya dengan imbalan penilaian baik","s":1}],"ex":"Objektivitas penilaian menjaga integritas evaluasi dan membantunya berkembang."},
{"id":"TKP-4760","q":"Dalam evaluasi tim, terjadi saling serang antar anggota. Cara terbaik adalah ....","opts":[{"t":"Menghentikan dan mengarahkan kembali pada aturan evaluasi yang membangun","s":5},{"t":"Menengahi dengan mengingatkan tujuan evaluasi","s":4},{"t":"Membiarkan saling serang sampai puas","s":3},{"t":"Ikut menyerang pihak yang Anda tidak sukai","s":2},{"t":"Keluar dari forum evaluasi","s":1}],"ex":"Penegakan aturan evaluasi yang membangun menghentikan saling serang."},
{"id":"TKP-4761","q":"Seorang anggota tim berprestasi rendah tetapi sangat loyal. Sikap terbaik Anda dalam evaluasi adalah ....","opts":[{"t":"Menilai objektif sambil mengusulkan pembinaan sesuai potensinya","s":5},{"t":"Mengapresiasi loyalitasnya dan membantu meningkatkan kinerjanya","s":4},{"t":"Memberi nilai tinggi karena loyalitasnya","s":3},{"t":"Memberi nilai rendah tanpa pembinaan","s":2},{"t":"Mengusulkan pemecatannya","s":1}],"ex":"Penilaian objektif disertai pembinaan menyeimbangkan loyalitas dan kinerja."},
{"id":"TKP-4762","q":"Tim Anda tidak memiliki indikator kinerja yang jelas untuk evaluasi. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan penyusunan indikator kinerja yang terukur dan disepakati","s":5},{"t":"Berinisiatif mencatat capaian tim sebagai bahan evaluasi","s":4},{"t":"Membiarkannya karena indikator itu rumit","s":3},{"t":"Menilai berdasarkan perasaan","s":2},{"t":"Menolak dievaluasi tanpa indikator","s":1}],"ex":"Indikator terukur yang disepakati membuat evaluasi adil dan objektif."},
{"id":"TKP-4763","q":"Seorang rekan satu tim selalu membela diri berlebihan saat dievaluasi. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menyampaikan evaluasi berbasis fakta dengan bahasa yang tidak menyerang","s":5},{"t":"Memberinya kesempatan menyampaikan pembelaan secara proporsional","s":4},{"t":"Menyerangnya lebih keras","s":3},{"t":"Berhenti mengevaluasinya","s":2},{"t":"Menertawakannya","s":1}],"ex":"Fakta dan bahasa tidak menyerang membuat evaluasi bisa diterima."},
{"id":"TKP-4764","q":"Hasil evaluasi tim Anda bocor ke pihak luar. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengusulkan aturan kerahasiaan evaluasi dan menelusuri kebocorannya","s":5},{"t":"Mengingatkan seluruh tim tentang etika kerahasiaan","s":4},{"t":"Membiarkannya karena sudah bocor","s":3},{"t":"Menuduh seseorang tanpa bukti","s":2},{"t":"Ikut menyebarkan hasil evaluasi","s":1}],"ex":"Aturan kerahasiaan dan penelusuran menjaga kepercayaan evaluasi."},
{"id":"TKP-4765","q":"Seorang anggota tim menangis saat menerima umpan balik negatif. Tindakan paling tepat adalah ....","opts":[{"t":"Memberinya waktu tenang lalu menyampaikan dengan lebih empatik","s":5},{"t":"Menegaskan niat baik Anda dan fokus pada solusi","s":4},{"t":"Membatalkan umpan balik tersebut","s":3},{"t":"Menertawakannya karena cengeng","s":2},{"t":"Melanjutkan dengan nada lebih keras","s":1}],"ex":"Empati dan jeda waktu membuat umpan balik sulit bisa diterima."},
{"id":"TKP-4766","q":"Tim Anda hanya mengevaluasi saat ada masalah besar. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan evaluasi berkala sebagai pencegahan, bukan hanya saat krisis","s":5},{"t":"Mencontohkan refleksi rutin dalam pekerjaan sehari-hari","s":4},{"t":"Membiarkan pola evaluasi saat krisis","s":3},{"t":"Menuntut evaluasi setiap hari","s":2},{"t":"Menolak evaluasi saat krisis","s":1}],"ex":"Evaluasi berkala mencegah masalah membesar menjadi krisis."},
{"id":"TKP-4767","q":"Seorang rekan satu tim memberi Anda umpan balik yang menurut Anda tidak tepat. Sikap terbaik Anda adalah ....","opts":[{"t":"Mendengarkan dengan terbuka, memverifikasi, lalu mengambil yang bermanfaat","s":5},{"t":"Mendiskusikannya dengannya untuk memahami maksudnya","s":4},{"t":"Menolak mentah-mentah","s":3},{"t":"Membalas dengan umpan balik negatif","s":2},{"t":"Memusuhinya","s":1}],"ex":"Keterbukaan dan verifikasi mengubah umpan balik keliru menjadi pembelajaran."},
{"id":"TKP-4768","q":"Dalam evaluasi tim, kontribusi anggota yang pendiam sering terlewat. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan metode evaluasi yang menggali kontribusi semua anggota","s":5},{"t":"Aktif menyampaikan kontribusi anggota pendiam yang Anda ketahui","s":4},{"t":"Membiarkannya terlewat","s":3},{"t":"Mengarang kontribusi untuknya","s":2},{"t":"Mengabaikan anggota pendiam","s":1}],"ex":"Metode inklusif memastikan kontribusi semua anggota tercatat adil."},
{"id":"TKP-4769","q":"Seorang anggota tim menggunakan hasil evaluasi untuk menjatuhkan rekan lain. Cara terbaik adalah ....","opts":[{"t":"Menegaskan bahwa hasil evaluasi untuk perbaikan, bukan senjata menyerang","s":5},{"t":"Menegurnya secara pribadi atas penyalahgunaan tersebut","s":4},{"t":"Membiarkannya","s":3},{"t":"Ikut menjatuhkan juga","s":2},{"t":"Menyembunyikan semua hasil evaluasi","s":1}],"ex":"Penegasan tujuan evaluasi mencegah penyalahgunaan hasil."},
{"id":"TKP-4770","q":"Tim Anda berhasil mencapai target dan tiba saatnya evaluasi keberhasilan. Sikap terbaik Anda adalah ....","opts":[{"t":"Menganalisis faktor keberhasilan untuk direplikasi dan merayakannya bersama","s":5},{"t":"Memberi apresiasi kepada seluruh anggota tim","s":4},{"t":"Menganggapnya biasa saja","s":3},{"t":"Mengklaim keberhasilan untuk diri sendiri","s":2},{"t":"Langsung melupakan dan pindah ke tugas lain","s":1}],"ex":"Analisis faktor keberhasilan dan perayaan bersama memperkuat tim."},
{"id":"TKP-4771","q":"Seorang rekan satu tim tidak pernah menindaklanjuti umpan balik yang diterimanya. Tindakan paling tepat adalah ....","opts":[{"t":"Mengingatkannya dengan baik dan menawarkan bantuan menindaklanjutinya","s":5},{"t":"Mendiskusikan hambatan yang membuatnya tidak menindaklanjuti","s":4},{"t":"Berhenti memberinya umpan balik","s":3},{"t":"Memaksanya menindaklanjuti","s":2},{"t":"Menghukumnya","s":1}],"ex":"Pengingat baik dan bantuan mengatasi hambatan tindak lanjut."},
{"id":"TKP-4772","q":"Evaluasi tim Anda selalu berfokus pada kesalahan, bukan keberhasilan. Cara terbaik adalah ....","opts":[{"t":"Mengusulkan evaluasi berimbang yang membahas keberhasilan dan perbaikan","s":5},{"t":"Menyampaikan keberhasilan tim dalam forum evaluasi","s":4},{"t":"Membiarkan fokus pada kesalahan","s":3},{"t":"Menolak dievaluasi","s":2},{"t":"Membalas dengan menyalahkan evaluator","s":1}],"ex":"Evaluasi berimbang memotivasi sekaligus memperbaiki."},
{"id":"TKP-4773","q":"Seorang anggota tim meminta umpan balik anonim tentang dirinya. Sikap terbaik Anda adalah ....","opts":[{"t":"Memberi umpan balik jujur dan membangun melalui mekanisme yang disepakati","s":5},{"t":"Menyampaikan secara tertulis dengan bahasa yang baik","s":4},{"t":"Menolak karena tidak berani","s":3},{"t":"Memberi umpan balik palsu yang manis","s":2},{"t":"Menggunakannya untuk menyerang anonim","s":1}],"ex":"Kejujuran membangun lewat mekanisme anonim tetap bermanfaat."},
{"id":"TKP-4774","q":"Tim Anda gagal total dalam proyek dan suasana evaluasi sangat tegang. Tindakan paling tepat adalah ....","opts":[{"t":"Membuka evaluasi dengan mengakui kegagalan bersama dan fokus pada pembelajaran","s":5},{"t":"Menciptakan suasana aman agar semua berani bicara jujur","s":4},{"t":"Saling menyalahkan untuk mencari kambing hitam","s":3},{"t":"Membatalkan evaluasi karena terlalu tegang","s":2},{"t":"Menyembunyikan kegagalan","s":1}],"ex":"Pengakuan bersama dan fokus pembelajaran mengubah kegagalan menjadi modal."},
{"id":"TKP-4775","q":"Seorang rekan satu tim hanya mau menerima umpan balik dari orang tertentu. Cara terbaik menyikapinya adalah ....","opts":[{"t":"Menghormatinya sambil membangun kepercayaan agar mau menerima dari semua","s":5},{"t":"Meminta orang kepercayaannya menyampaikan umpan balik tim","s":4},{"t":"Memaksanya menerima dari semua orang","s":3},{"t":"Berhenti memberinya umpan balik","s":2},{"t":"Mengejeknya pilih-pilih","s":1}],"ex":"Membangun kepercayaan bertahap membuka keterbukaan menerima umpan balik."}
,
{"id":"TKP-4776","q":"Tim Anda mendapat tenggat sangat mepet untuk pekerjaan besar. Tindakan paling tepat adalah ....","opts":[{"t":"Menyusun rencana kerja prioritas dan membagi tugas secara optimal","s":5},{"t":"Mengajak tim fokus dan saling mendukung melewati masa kritis","s":4},{"t":"Panik dan bekerja tanpa rencana","s":3},{"t":"Menolak tenggat tersebut","s":2},{"t":"Menyerah sebelum mencoba","s":1}],"ex":"Rencana prioritas dan dukungan tim mengubah tekanan menjadi fokus."},
{"id":"TKP-4777","q":"Di tengah tekanan tenggat, dua anggota tim Anda bertengkar hebat. Sikap terbaik Anda adalah ....","opts":[{"t":"Melerai dengan tegas namun bijak dan mengajak kembali fokus pada tenggat","s":5},{"t":"Menunda penyelesaian konflik sampai tenggat terlewati dengan damai","s":4},{"t":"Membiarkan mereka bertengkar","s":3},{"t":"Memihak salah satu","s":2},{"t":"Ikut bertengkar","s":1}],"ex":"Penanganan tegas namun bijak menjaga fokus tim di masa kritis."},
{"id":"TKP-4778","q":"Seorang anggota tim Anda sakit di tengah pengerjaan proyek mendesak. Tindakan paling tepat adalah ....","opts":[{"t":"Menata ulang pembagian tugas dan memintanya fokus pada pemulihan","s":5},{"t":"Membagi tugasnya sementara kepada anggota lain yang mampu","s":4},{"t":"Memaksanya tetap bekerja","s":3},{"t":"Membiarkan tugasnya terbengkalai","s":2},{"t":"Menyalahkannya karena sakit di saat genting","s":1}],"ex":"Penataan ulang tugas dan kepedulian pada kesehatan menjaga tim dan manusia."},
{"id":"TKP-4779","q":"Tim Anda harus lembur berhari-hari mengejar tenggat. Cara terbaik menjaga kekompakan adalah ....","opts":[{"t":"Memastikan beban terbagi adil, saling mendukung, dan ada jeda istirahat","s":5},{"t":"Memberi apresiasi dan menjaga komunikasi positif","s":4},{"t":"Memaksa lembur tanpa jeda","s":3},{"t":"Membiarkan yang lemah menyerah","s":2},{"t":"Menyalahkan yang mengeluh","s":1}],"ex":"Keadilan beban, dukungan, dan istirahat menjaga tim tetap solid saat lembur."},
{"id":"TKP-4780","q":"Di bawah tekanan, seorang rekan satu tim menyalahkan Anda atas keterlambatan. Sikap terbaik Anda adalah ....","opts":[{"t":"Tetap tenang, fokus pada solusi, dan membahasnya setelah tekanan mereda","s":5},{"t":"Menjelaskan fakta dengan kepala dingin tanpa emosi","s":4},{"t":"Membalas menyalahkannya","s":3},{"t":"Menangis dan menyerah","s":2},{"t":"Menyimpan dendam","s":1}],"ex":"Ketenangan dan fokus solusi lebih penting daripada pembelaan saat tertekan."},
{"id":"TKP-4781","q":"Peralatan kerja tim rusak di tengah tenggat kritis. Tindakan paling tepat adalah ....","opts":[{"t":"Segera mencari solusi alternatif sambil mengatur ulang alur kerja tim","s":5},{"t":"Membagi tim menjadi yang memperbaiki dan yang melanjutkan dengan cara lain","s":4},{"t":"Berhenti bekerja menunggu perbaikan","s":3},{"t":"Panik dan saling menyalahkan","s":2},{"t":"Menyerah pada tenggat","s":1}],"ex":"Solusi alternatif dan pengaturan ulang alur menjaga progres meski ada kendala."},
{"id":"TKP-4782","q":"Tim Anda menerima perubahan permintaan mendadak di tengah pengerjaan. Cara terbaik adalah ....","opts":[{"t":"Menilai dampak perubahan dan menyesuaikan rencana bersama tim","s":5},{"t":"Mendiskusikan prioritas baru dengan seluruh anggota","s":4},{"t":"Menolak perubahan itu","s":3},{"t":"Mengikuti perubahan tanpa rencana","s":2},{"t":"Menyalahkan pemberi perubahan","s":1}],"ex":"Penilaian dampak dan penyesuaian bersama mengelola perubahan mendadak."},
{"id":"TKP-4783","q":"Seorang anggota tim Anda mengundurkan diri di tengah proyek penting. Tindakan paling tepat adalah ....","opts":[{"t":"Menata ulang tugas dan peran dengan cepat bersama tim yang tersisa","s":5},{"t":"Mendiskusikan beban tambahan secara terbuka dan adil","s":4},{"t":"Panik dan menyalahkan yang mengundurkan diri","s":3},{"t":"Membiarkan kekosongan tanpa penataan","s":2},{"t":"Memaksa yang keluar untuk tetap bekerja","s":1}],"ex":"Penataan ulang cepat dan diskusi terbuka menjaga proyek tetap berjalan."},
{"id":"TKP-4784","q":"Di bawah tekanan berat, komunikasi tim Anda menjadi kasar dan tidak sehat. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengingatkan dengan tenang pentingnya komunikasi baik meski tertekan","s":5},{"t":"Mencontohkan komunikasi positif dalam setiap interaksi","s":4},{"t":"Ikut berkomunikasi kasar","s":3},{"t":"Diam dan menarik diri","s":2},{"t":"Membalas kekasaran dengan kekasaran","s":1}],"ex":"Keteladanan komunikasi positif menular lebih kuat daripada tekanan."},
{"id":"TKP-4785","q":"Tim Anda terancam gagal memenuhi tenggat besok pagi. Tindakan paling tepat malam ini adalah ....","opts":[{"t":"Mengidentifikasi bagian kritis dan mengerahkan upaya tim ke sana","s":5},{"t":"Membagi shift kerja agar tim tetap punya istirahat","s":4},{"t":"Bekerja semalaman tanpa rencana","s":3},{"t":"Menyerah dan tidur","s":2},{"t":"Memalsukan hasil pekerjaan","s":1}],"ex":"Fokus pada bagian kritis dan pembagian shift memaksimalkan peluang tenggat."},
{"id":"TKP-4786","q":"Seorang rekan satu tim pingsan karena kelelahan mengejar tenggat. Tindakan paling tepat adalah ....","opts":[{"t":"Mengutamakan pertolongan dan kesehatannya, lalu menata ulang beban tim","s":5},{"t":"Membawanya beristirahat dan memastikan ia mendapat perawatan","s":4},{"t":"Membiarkannya dan terus bekerja","s":3},{"t":"Memaksanya bangun dan lanjut bekerja","s":2},{"t":"Menyalahkannya karena tidak kuat","s":1}],"ex":"Kesehatan anggota selalu lebih utama daripada tenggat apa pun."},
{"id":"TKP-4787","q":"Di tengah krisis, seorang anggota tim mengusulkan jalan pintas yang berisiko. Sikap terbaik Anda adalah ....","opts":[{"t":"Menilai risiko bersama dan hanya mengambil jalan aman yang disepakati","s":5},{"t":"Mendiskusikan konsekuensi jalan pintas itu secara terbuka","s":4},{"t":"Langsung mengikuti jalan pintasnya","s":3},{"t":"Menolak tanpa mendengar penjelasannya","s":2},{"t":"Menyalahkannya karena mengusulkan hal berisiko","s":1}],"ex":"Penilaian risiko bersama mencegah jalan pintas yang membahayakan."},
{"id":"TKP-4788","q":"Tim Anda berhasil melewati masa kritis dengan baik. Tindakan paling tepat setelahnya adalah ....","opts":[{"t":"Mengevaluasi pelajaran dari masa kritis dan mengapresiasi seluruh tim","s":5},{"t":"Memberi waktu pemulihan yang cukup bagi anggota","s":4},{"t":"Langsung memberi beban berat berikutnya","s":3},{"t":"Melupakan dan tidak membahasnya","s":2},{"t":"Mengklaim keberhasilan untuk diri sendiri","s":1}],"ex":"Evaluasi pelajaran dan apresiasi mengubah krisis menjadi penguatan tim."},
{"id":"TKP-4789","q":"Seorang anggota tim menyerah di tengah tekanan dan ingin keluar. Cara terbaik adalah ....","opts":[{"t":"Mendengarkan keluhannya, memberi dukungan, dan mencari solusi bebannya","s":5},{"t":"Mengingatkannya pada komitmen dan tujuan bersama tim","s":4},{"t":"Membiarkannya keluar tanpa usaha","s":3},{"t":"Memaksanya bertahan dengan ancaman","s":2},{"t":"Mengejeknya lemah","s":1}],"ex":"Dukungan dan solusi beban memberi kekuatan untuk bertahan."},
{"id":"TKP-4790","q":"Dalam situasi darurat, tidak ada pemimpin tim yang hadir mengambil keputusan. Sikap terbaik Anda adalah ....","opts":[{"t":"Mengambil inisiatif mengoordinasikan tim berdasarkan kesepakatan darurat","s":5},{"t":"Mengajak anggota lain bermusyawarah cepat mengambil keputusan","s":4},{"t":"Menunggu pemimpin datang","s":3},{"t":"Masing-masing bertindak sendiri","s":2},{"t":"Panik dan tidak berbuat apa-apa","s":1}],"ex":"Inisiatif koordinasi dan musyawarah cepat mengisi kekosongan kepemimpinan."},
{"id":"TKP-4791","q":"Tim Anda diminta mengerjakan dua proyek kritis bersamaan dengan personel terbatas. Tindakan paling tepat adalah ....","opts":[{"t":"Mengusulkan prioritas dan jadwal realistis yang disepakati semua pihak","s":5},{"t":"Membagi tim menjadi dua kelompok fokus dengan koordinator masing-masing","s":4},{"t":"Mengerjakan keduanya asal-asalan","s":3},{"t":"Menolak salah satunya tanpa diskusi","s":2},{"t":"Membiarkan tim kelelahan mengerjakan keduanya","s":1}],"ex":"Prioritas realistis dan pembagian fokus menjaga kualitas kedua proyek."},
{"id":"TKP-4792","q":"Seorang rekan satu tim membuat kesalahan besar akibat terburu-buru mengejar tenggat. Sikap terbaik Anda adalah ....","opts":[{"t":"Membantu memperbaikinya dan mengusulkan pengendalian kualitas meski mepet","s":5},{"t":"Menenangkannya lalu mencari solusi perbaikan bersama","s":4},{"t":"Memarahinya habis-habisan","s":3},{"t":"Membiarkan kesalahannya","s":2},{"t":"Melaporkannya sebagai kegagalan","s":1}],"ex":"Bantuan perbaikan dan pengendalian kualitas menyelesaikan tanpa menyalahkan."},
{"id":"TKP-4793","q":"Di bawah tekanan, Anda merasa tidak mampu menyelesaikan bagian tugas tim Anda. Tindakan paling tepat adalah ....","opts":[{"t":"Jujur kepada tim dan meminta bantuan atau penyesuaian tugas","s":5},{"t":"Meminta bimbingan rekan yang lebih mampu","s":4},{"t":"Menyembunyikan ketidakmampuan sampai tenggat tiba","s":3},{"t":"Menyerah diam-diam","s":2},{"t":"Menyalahkan orang lain","s":1}],"ex":"Kejujuran dan meminta bantuan lebih baik daripada kegagalan diam-diam."},
{"id":"TKP-4794","q":"Tim Anda terpecah pendapat soal strategi di tengah tenggat yang mepet. Cara terbaik adalah ....","opts":[{"t":"Memutuskan cepat lewat musyawarah singkat dengan komitmen penuh semua anggota","s":5},{"t":"Memilih strategi dengan risiko terkecil yang disepakati","s":4},{"t":"Berdebat panjang sampai tenggat terlewat","s":3},{"t":"Masing-masing memakai strateginya sendiri","s":2},{"t":"Menyerah pada tenggat","s":1}],"ex":"Keputusan cepat lewat musyawarah singkat dengan komitmen penuh menyelamatkan tenggat."},
{"id":"TKP-4795","q":"Seorang anggota tim memanipulasi laporan progres agar terlihat baik di masa kritis. Tindakan paling tepat adalah ....","opts":[{"t":"Menegakkan kejujuran pelaporan karena keputusan berbasis data palsu berbahaya","s":5},{"t":"Menegurnya secara pribadi dan meminta laporan yang sebenarnya","s":4},{"t":"Membiarkannya demi moral tim","s":3},{"t":"Ikut memanipulasi laporan","s":2},{"t":"Menyebarkan kecurangannya","s":1}],"ex":"Kejujuran pelaporan melindungi tim dari keputusan berbasis data palsu."},
{"id":"TKP-4796","q":"Setelah lembur panjang, anggota tim Anda kelelahan dan mudah tersinggung. Sikap terbaik Anda adalah ....","opts":[{"t":"Memberi pengertian, menjaga suasana positif, dan mengusulkan jeda istirahat","s":5},{"t":"Mengurangi interaksi yang tidak perlu dan fokus pada pekerjaan","s":4},{"t":"Tersinggung balik","s":3},{"t":"Menegur mereka karena tidak profesional","s":2},{"t":"Mengabaikan kelelahan mereka","s":1}],"ex":"Pengertian dan jeda istirahat memulihkan energi dan suasana tim."},
{"id":"TKP-4797","q":"Tim Anda harus mempresentasikan hasil di depan pimpinan dalam waktu satu jam. Tindakan paling tepat adalah ....","opts":[{"t":"Membagi peran presentasi cepat dan menyiapkan poin kunci bersama","s":5},{"t":"Menunjuk yang paling siap tampil dengan dukungan data dari semua","s":4},{"t":"Panik dan tidak menyiapkan apa-apa","s":3},{"t":"Saling tunjuk siapa yang presentasi","s":2},{"t":"Membatalkan presentasi","s":1}],"ex":"Pembagian peran cepat dan poin kunci bersama memaksimalkan persiapan mepet."},
{"id":"TKP-4798","q":"Di tengah tekanan, seorang rekan justru bercanda berlebihan mengganggu fokus tim. Cara terbaik adalah ....","opts":[{"t":"Mengingatkannya dengan baik bahwa tim butuh fokus, apresiasi niat menghiburnya","s":5},{"t":"Mengajaknya menyalurkan humor di waktu istirahat","s":4},{"t":"Membiarkannya mengganggu","s":3},{"t":"Memarahinya dengan kasar","s":2},{"t":"Mengeluarkannya dari ruangan","s":1}],"ex":"Pengingat baik dan penyaluran di waktu tepat menjaga fokus tanpa mematikan keceriaan."},
{"id":"TKP-4799","q":"Tenggat proyek tim Anda dipercepat tiba-tiba menjadi separuh waktu semula. Sikap terbaik Anda adalah ....","opts":[{"t":"Menyusun ulang rencana dan prioritas bersama tim secara cepat","s":5},{"t":"Mengomunikasikan kendala realistis sambil menunjukkan upaya maksimal","s":4},{"t":"Protes dan menolak tenggat baru","s":3},{"t":"Bekerja asal-asalan mengejar waktu","s":2},{"t":"Menyerah sebelum mencoba","s":1}],"ex":"Penyusunan ulang rencana cepat mengubah tenggat mepet menjadi tantangan terkelola."},
{"id":"TKP-4800","q":"Setelah melewati masa kritis, konflik yang tertunda antar anggota tim muncul kembali. Tindakan paling tepat adalah ....","opts":[{"t":"Memfasilitasi penyelesaian konflik yang tertunda selagi tim masih solid","s":5},{"t":"Mengajak berdialog terbuka dalam suasana yang sudah tenang","s":4},{"t":"Membiarkannya karena masa kritis sudah lewat","s":3},{"t":"Menunda lagi sampai ada krisis berikutnya","s":2},{"t":"Memihak salah satu pihak","s":1}],"ex":"Menyelesaikan konflik tertunda saat tenang mencegah ledakan di masa depan."}
];
